insert into public.countries (code, name, capital, has_sheet, disputed, location, population_note, currency, official_language, motto, flag_note, independence_date, independence_text, fun_fact, sheet, editorial_status, validation_note) values ('CI', 'Côte d''Ivoire', 'Yamoussoukro (capitale politique) ; Abidjan est la capitale économique', true, false, 'Afrique de l''Ouest, sur le golfe de Guinée. Voisins : Liberia, Guinée, Mali, Burkina Faso et Ghana.', 'Plus de 30 millions d''habitants (estimation)', 'Franc CFA (XOF)', 'Français', 'Union, Discipline, Travail', 'Trois bandes verticales : orange, blanc et vert.', '7 août 1960', 'La Côte d''Ivoire devient indépendante le 7 août 1960. Félix Houphouët-Boigny en est le premier président.', 'Le parc national de Taï abrite des chimpanzés qui utilisent des pierres pour casser des noix.', '{"history":["Avant la colonisation, le territoire accueillait des royaumes comme celui de Kong au nord ou des royaumes akan à l''est.","Grand-Bassam fut la première capitale de la colonie française."],"languages":["Le français est la langue officielle.","Plus de soixante langues sont parlées, dont le baoulé, le dioula, le bété, le sénoufo et l''agni."],"cultures":["Les masques et les danses tiennent une grande place dans de nombreuses communautés.","La musique ivoirienne (zouglou, coupé-décalé) est populaire dans toute l''Afrique."],"heritage":["La ville historique de Grand-Bassam, inscrite au patrimoine mondial.","La basilique Notre-Dame-de-la-Paix de Yamoussoukro."],"nature":["Le parc national de Taï, une des dernières grandes forêts primaires d''Afrique de l''Ouest.","Le parc national de la Comoé.","Le mont Nimba, partagé avec la Guinée."],"economy":["La Côte d''Ivoire est le premier producteur mondial de cacao.","On y cultive aussi le café, l''anacarde (noix de cajou), l''hévéa et le palmier à huile."],"sciences":["Abidjan est devenue un pôle important du numérique et des start-up en Afrique de l''Ouest."],"sources":[{"title":"Liste du patrimoine mondial","publisher":"UNESCO","url":"https://whc.unesco.org/fr/list/"}]}'::jsonb, 'verifie', null) on conflict (code) do nothing;
