insert into public.countries (code, name, capital, has_sheet, disputed, location, population_note, currency, official_language, motto, flag_note, independence_date, independence_text, fun_fact, sheet, editorial_status, validation_note) values ('GH', 'Ghana', 'Accra', true, false, 'Afrique de l''Ouest, sur le golfe de Guinée, entre la Côte d''Ivoire, le Burkina Faso et le Togo.', 'Plus de 33 millions d''habitants (estimation)', 'Cedi ghanéen (GHS)', 'Anglais', 'Freedom and Justice (Liberté et Justice)', 'Trois bandes horizontales rouge, or et vert, avec une étoile noire au centre.', '6 mars 1957', 'Ancienne colonie britannique de la Gold Coast (Côte-de-l''Or), le Ghana devient indépendant le 6 mars 1957, avec Kwame Nkrumah à sa tête. C''est l''un des premiers pays d''Afrique subsaharienne à obtenir son indépendance.', '« Ghana » a été choisi en hommage à l''un des plus anciens empires d''Afrique de l''Ouest.', '{"history":["Le pays a pris le nom de l''ancien Empire du Ghana, même si celui-ci se trouvait plus au nord, entre les actuels Mali et Mauritanie.","Le royaume ashanti, avec Kumasi pour capitale, fut un État puissant ; le Tabouret d''or en est le symbole sacré."],"languages":["L''anglais est la langue officielle.","On parle aussi les langues akan (twi, fante), l''éwé, le ga, le dagbani et beaucoup d''autres."],"cultures":["Le tissu kente, aux bandes tissées colorées, et les symboles adinkra sont connus dans le monde entier.","La musique highlife est née au Ghana."],"heritage":["Les forts et châteaux de la côte, comme ceux de Cape Coast et d''Elmina, inscrits au patrimoine mondial : ils rappellent l''histoire de la traite."],"nature":["Le lac Volta, l''un des plus grands lacs artificiels du monde, créé par le barrage d''Akosombo.","Le parc national de Kakum et son chemin suspendu dans la canopée."],"economy":["Le Ghana est l''un des premiers producteurs mondiaux de cacao et un grand producteur d''or."],"sciences":["Le barrage d''Akosombo produit une grande part de l''électricité du pays."],"sources":[{"title":"Liste du patrimoine mondial","publisher":"UNESCO","url":"https://whc.unesco.org/fr/list/"}]}'::jsonb, 'verifie', null) on conflict (code) do nothing;
insert into public.personalities (country_id, name, role, editorial_status) select id, 'Kwame Nkrumah', 'Premier dirigeant du Ghana indépendant, militant du panafricanisme', 'verifie' from public.countries where code = 'GH' on conflict do nothing;
insert into public.personalities (country_id, name, role, editorial_status) select id, 'Kofi Annan', 'Secrétaire général des Nations unies (1997-2006), prix Nobel de la paix 2001', 'verifie' from public.countries where code = 'GH' on conflict do nothing;
insert into public.personalities (country_id, name, role, editorial_status) select id, 'Yaa Asantewaa', 'Reine mère ashanti, figure de la résistance en 1900', 'verifie' from public.countries where code = 'GH' on conflict do nothing;
insert into public.countries (code, name, capital, has_sheet, disputed, location, population_note, currency, official_language, motto, flag_note, independence_date, independence_text, fun_fact, sheet, editorial_status, validation_note) values ('GN', 'Guinée', 'Conakry', true, false, 'Afrique de l''Ouest, au bord de l''océan Atlantique. La Guinée a des frontières avec la Guinée-Bissau, le Sénégal, le Mali, la Côte d''Ivoire, le Liberia et la Sierra Leone.', 'Plus de 13 millions d''habitants (estimation)', 'Franc guinéen (GNF)', 'Français', 'Travail, Justice, Solidarité', 'Trois bandes verticales : rouge, jaune et vert.', '2 octobre 1958', 'Le 28 septembre 1958, la Guinée vote « non » au référendum proposé par la France et proclame son indépendance quatre jours plus tard. Elle est la première colonie française d''Afrique subsaharienne à devenir indépendante.', 'Le nom des quatre régions naturelles décrit le paysage : Guinée maritime, Moyenne-Guinée, Haute-Guinée et Guinée forestière.', '{"history":["Une partie du territoire de la Guinée actuelle appartenait à l''Empire du Mali, fondé au XIIIe siècle selon la tradition orale par Soundiata Keïta.","Au XVIIIe siècle naît dans le Fouta-Djalon un État appelé l''Imamat (ou Almamiat) du Fouta-Djalon, avec Timbo pour capitale.","À la fin du XIXe siècle, l''almamy Samory Touré résiste longtemps à la conquête coloniale française avant d''être capturé en 1898.","La colonie de la « Guinée française » fait partie de l''Afrique-Occidentale française (AOF) jusqu''à l''indépendance de 1958."],"languages":["Le français est la langue officielle.","De nombreuses langues nationales sont parlées : pular, maninka, susu, kissi, kpelle (guerzé), loma (toma) et d''autres encore."],"cultures":["Le pays rassemble de nombreuses communautés, chacune avec ses langues, ses fêtes et ses savoir-faire, et des différences d''une région à l''autre.","La musique y tient une place immense : balafon, kora, djembé, et des orchestres modernes devenus célèbres."],"heritage":["L''Espace culturel du Sosso-Bala, à Niagassola, reconnu par l''UNESCO comme patrimoine culturel immatériel.","La Réserve naturelle intégrale du mont Nimba, inscrite au patrimoine mondial de l''UNESCO (partagée avec la Côte d''Ivoire)."],"nature":["Le massif du Fouta-Djalon, surnommé le « château d''eau de l''Afrique de l''Ouest » : de grands fleuves y prennent leur source, comme le Sénégal (par le Bafing) et la Gambie. Le Niger naît lui aussi dans les hauteurs guinéennes.","Le mont Nimba, point culminant du pays (environ 1 752 m).","Les îles de Loos, au large de Conakry."],"economy":["La Guinée possède parmi les plus grandes réserves de bauxite au monde, le minerai qui sert à fabriquer l''aluminium.","L''agriculture fait vivre une grande partie de la population : riz, manioc, fonio, fruits (mangues, ananas, bananes), café en Guinée forestière."],"sciences":["L''énergie hydroélectrique est développée grâce aux nombreux cours d''eau, par exemple avec le barrage de Kaléta sur le fleuve Konkouré."],"sources":[{"title":"Liste du patrimoine mondial","publisher":"UNESCO","url":"https://whc.unesco.org/fr/list/"},{"title":"Liste représentative du patrimoine culturel immatériel","publisher":"UNESCO","url":"https://ich.unesco.org/fr/listes"},{"title":"Fiche pays Guinée","publisher":"Encyclopædia Universalis / Britannica (à consulter en bibliothèque)"}]}'::jsonb, 'verifie', 'Le chiffre de population est une estimation à actualiser avec l''Institut national de la statistique de Guinée.') on conflict (code) do nothing;
insert into public.personalities (country_id, name, role, editorial_status) select id, 'Camara Laye', 'Écrivain, auteur de L''Enfant noir (1953)', 'verifie' from public.countries where code = 'GN' on conflict do nothing;
insert into public.personalities (country_id, name, role, editorial_status) select id, 'Samory Touré', 'Bâtisseur d''un État et résistant à la colonisation (XIXe siècle)', 'verifie' from public.countries where code = 'GN' on conflict do nothing;
insert into public.personalities (country_id, name, role, editorial_status) select id, 'Ahmed Sékou Touré', 'Premier président de la Guinée indépendante (1958-1984)', 'verifie' from public.countries where code = 'GN' on conflict do nothing;
insert into public.personalities (country_id, name, role, editorial_status) select id, 'Mory Kanté', 'Chanteur et joueur de kora, connu dans le monde entier', 'verifie' from public.countries where code = 'GN' on conflict do nothing;
insert into public.personalities (country_id, name, role, editorial_status) select id, 'Tierno Monénembo', 'Écrivain, prix Renaudot 2008', 'verifie' from public.countries where code = 'GN' on conflict do nothing;
