insert into public.countries (code, name, capital, has_sheet, disputed, location, population_note, currency, official_language, motto, flag_note, independence_date, independence_text, fun_fact, sheet, editorial_status, validation_note) values ('ML', 'Mali', 'Bamako', true, false, 'Afrique de l''Ouest, sans accès à la mer. Le fleuve Niger traverse le pays en formant une grande boucle.', 'Plus de 22 millions d''habitants (estimation)', 'Franc CFA (XOF)', 'Voir la Constitution en vigueur (plusieurs langues nationales)', null, 'Trois bandes verticales : vert, jaune et rouge.', '22 septembre 1960', 'Le Mali proclame son indépendance le 22 septembre 1960. Modibo Keïta en est le premier président.', 'La grande mosquée de Djenné est l''un des plus grands édifices en terre crue du monde ; ses murs sont recrépis lors d''une fête collective.', '{"history":["Le territoire a vu naître de grands États : l''Empire du Ghana (Wagadou), l''Empire du Mali puis l''Empire songhaï.","En 1324, le souverain du Mali Mansa Moussa fait un pèlerinage à La Mecque resté célèbre pour l''or qu''il emporta.","Tombouctou fut un grand centre d''études et de manuscrits."],"languages":["Le bambara (bamanankan) est la langue la plus parlée.","On parle aussi le peul (fulfulde), le soninké, le songhaï, le tamasheq, le dogon et d''autres langues."],"cultures":["Les griots transmettent l''histoire et les généalogies par la parole et la musique.","La Charte du Manden, proclamée à Kouroukan Fouga, est inscrite au patrimoine immatériel de l''UNESCO."],"heritage":["Tombouctou et la ville de Djenné, inscrites au patrimoine mondial.","Les falaises de Bandiagara (pays dogon).","Le tombeau des Askia à Gao."],"nature":["Le fleuve Niger et son delta intérieur, immense zone humide.","Le Sahel et le Sahara au nord."],"economy":["Agriculture (coton, mil, riz), élevage et exploitation de l''or."],"sciences":["Les manuscrits de Tombouctou contiennent des textes d''astronomie, de mathématiques et de médecine."],"sources":[{"title":"Liste du patrimoine mondial","publisher":"UNESCO","url":"https://whc.unesco.org/fr/list/"},{"title":"Charte du Manden, proclamée à Kouroukan Fouga","publisher":"UNESCO","url":"https://ich.unesco.org/fr/RL/la-charte-du-manden-proclamee-a-kouroukan-fouga-00290"}]}'::jsonb, 'a-valider', 'Le statut des langues officielles a évolué avec la Constitution de 2023 : à vérifier dans le texte en vigueur avant publication.') on conflict (code) do nothing;
insert into public.personalities (country_id, name, role, editorial_status) select id, 'Soundiata Keïta', 'Fondateur de l''Empire du Mali selon la tradition orale', 'verifie' from public.countries where code = 'ML' on conflict do nothing;
