insert into public.countries (code, name, capital, has_sheet, disputed, location, population_note, currency, official_language, motto, flag_note, independence_date, independence_text, fun_fact, sheet, editorial_status, validation_note) values ('SN', 'Sénégal', 'Dakar', true, false, 'Pointe la plus à l''ouest de l''Afrique continentale, au bord de l''océan Atlantique. La Gambie forme une bande de terre à l''intérieur du Sénégal.', 'Environ 18 millions d''habitants (estimation)', 'Franc CFA (XOF)', 'Français', 'Un Peuple, Un But, Une Foi', 'Trois bandes verticales vert, jaune et rouge, avec une étoile verte au centre.', '1960', 'Le Sénégal devient indépendant en 1960, d''abord au sein de la Fédération du Mali avec le Soudan français (actuel Mali), puis seul. La fête nationale est célébrée le 4 avril.', 'La pointe des Almadies, à Dakar, est le point le plus à l''ouest de l''Afrique continentale.', '{"history":["Avant la colonisation, plusieurs royaumes se sont succédé, comme le Djolof, le Cayor, le Baol, le Sine ou le Saloum.","Saint-Louis puis Dakar ont été des villes importantes de l''administration coloniale française.","Léopold Sédar Senghor, poète, devient le premier président du pays indépendant."],"languages":["Le français est la langue officielle.","Le wolof est très largement parlé ; on parle aussi le pulaar, le sérère, le diola, le mandinka, le soninké et d''autres langues."],"cultures":["La « teranga », l''hospitalité, est une valeur très importante.","Le thiéboudiène (ceebu jën), plat de riz au poisson, est inscrit au patrimoine culturel immatériel de l''UNESCO."],"heritage":["L''île de Gorée, lieu de mémoire de la traite des esclaves, inscrite au patrimoine mondial.","L''île de Saint-Louis, ancienne capitale."],"nature":["Le parc national du Niokolo-Koba.","Le parc national des oiseaux du Djoudj, étape de millions d''oiseaux migrateurs.","Le lac Rose (lac Retba)."],"economy":["Pêche, agriculture (arachide, mil, riz), tourisme et services.","Le port de Dakar est l''un des plus importants d''Afrique de l''Ouest."],"sciences":["L''université Cheikh-Anta-Diop de Dakar est l''une des plus anciennes universités d''Afrique de l''Ouest francophone."],"sources":[{"title":"Liste du patrimoine mondial","publisher":"UNESCO","url":"https://whc.unesco.org/fr/list/"},{"title":"Liste représentative du patrimoine culturel immatériel","publisher":"UNESCO","url":"https://ich.unesco.org/fr/listes"}]}'::jsonb, 'verifie', null) on conflict (code) do nothing;
insert into public.personalities (country_id, name, role, editorial_status) select id, 'Léopold Sédar Senghor', 'Poète et premier président du Sénégal', 'verifie' from public.countries where code = 'SN' on conflict do nothing;
