insert into public.regions (country_id, name, kind, description) select id, 'Guinée maritime', 'naturelle', 'La côte atlantique : climat chaud et humide, mangroves, rizières et ports.' from public.countries where code = 'GN' on conflict do nothing;
insert into public.regions (country_id, name, kind, description) select id, 'Moyenne-Guinée', 'naturelle', 'Plateaux, falaises et cascades ; un climat plus frais ; les sources de grands fleuves.' from public.countries where code = 'GN' on conflict do nothing;
insert into public.regions (country_id, name, kind, description) select id, 'Haute-Guinée', 'naturelle', 'Savanes traversées par le Niger et ses affluents ; le cœur de l''ancien Manding.' from public.countries where code = 'GN' on conflict do nothing;
insert into public.regions (country_id, name, kind, description) select id, 'Guinée forestière', 'naturelle', 'Forêts humides et montagnes, dont le mont Nimba, point culminant du pays.' from public.countries where code = 'GN' on conflict do nothing;
insert into public.regions (country_id, name, kind) select id, 'Conakry', 'administrative' from public.countries where code = 'GN' on conflict do nothing;
insert into public.cities (country_id, region_id, name, description, is_capital) select c.id, r.id, 'Conakry', 'La capitale, née sur l''île de Tombo et étendue sur la presqu''île de Kaloum. C''est le principal port du pays.', true from public.countries c join public.regions r on r.country_id = c.id and r.kind = 'naturelle' and r.name = 'Guinée maritime' where c.code = 'GN' on conflict do nothing;
insert into public.regions (country_id, name, kind) select id, 'Kindia', 'administrative' from public.countries where code = 'GN' on conflict do nothing;
insert into public.cities (country_id, region_id, name, description, is_capital) select c.id, r.id, 'Kindia', 'Ville réputée pour ses fruits (mangues, ananas, bananes). Non loin se trouve la cascade du « Voile de la Mariée ».', false from public.countries c join public.regions r on r.country_id = c.id and r.kind = 'naturelle' and r.name = 'Guinée maritime' where c.code = 'GN' on conflict do nothing;
insert into public.regions (country_id, name, kind) select id, 'Boké', 'administrative' from public.countries where code = 'GN' on conflict do nothing;
insert into public.cities (country_id, region_id, name, description, is_capital) select c.id, r.id, 'Boké', 'Ancien comptoir sur le Rio Nunez, au nord-ouest. La région possède d''immenses gisements de bauxite.', false from public.countries c join public.regions r on r.country_id = c.id and r.kind = 'naturelle' and r.name = 'Guinée maritime' where c.code = 'GN' on conflict do nothing;
insert into public.regions (country_id, name, kind) select id, 'Labé', 'administrative' from public.countries where code = 'GN' on conflict do nothing;
insert into public.cities (country_id, region_id, name, description, is_capital) select c.id, r.id, 'Labé', 'Grande ville du Fouta-Djalon, ancien chef-lieu d''une province importante de l''Imamat du Fouta-Djalon.', false from public.countries c join public.regions r on r.country_id = c.id and r.kind = 'naturelle' and r.name = 'Moyenne-Guinée' where c.code = 'GN' on conflict do nothing;
insert into public.regions (country_id, name, kind) select id, 'Mamou', 'administrative' from public.countries where code = 'GN' on conflict do nothing;
insert into public.cities (country_id, region_id, name, description, is_capital) select c.id, r.id, 'Mamou', 'Ville carrefour, sur les routes qui relient la côte, le Fouta-Djalon et la Haute-Guinée.', false from public.countries c join public.regions r on r.country_id = c.id and r.kind = 'naturelle' and r.name = 'Moyenne-Guinée' where c.code = 'GN' on conflict do nothing;
insert into public.regions (country_id, name, kind) select id, 'Kankan', 'administrative' from public.countries where code = 'GN' on conflict do nothing;
insert into public.cities (country_id, region_id, name, description, is_capital) select c.id, r.id, 'Kankan', 'Grande ville de Haute-Guinée sur la rivière Milo, ancien centre de commerce et d''enseignement. Elle accueille l''université Julius-Nyerere.', false from public.countries c join public.regions r on r.country_id = c.id and r.kind = 'naturelle' and r.name = 'Haute-Guinée' where c.code = 'GN' on conflict do nothing;
insert into public.regions (country_id, name, kind) select id, 'Faranah', 'administrative' from public.countries where code = 'GN' on conflict do nothing;
insert into public.cities (country_id, region_id, name, description, is_capital) select c.id, r.id, 'Faranah', 'Région proche des sources du Niger, avec le parc national du Haut-Niger. Ahmed Sékou Touré y est né en 1922.', false from public.countries c join public.regions r on r.country_id = c.id and r.kind = 'naturelle' and r.name = 'Haute-Guinée' where c.code = 'GN' on conflict do nothing;
insert into public.regions (country_id, name, kind) select id, 'N''Zérékoré', 'administrative' from public.countries where code = 'GN' on conflict do nothing;
insert into public.cities (country_id, region_id, name, description, is_capital) select c.id, r.id, 'N''Zérékoré', 'La plus grande ville de Guinée forestière, connue pour son grand marché, non loin du mont Nimba.', false from public.countries c join public.regions r on r.country_id = c.id and r.kind = 'naturelle' and r.name = 'Guinée forestière' where c.code = 'GN' on conflict do nothing;
insert into public.historical_events (country_id, when_label, title, description, is_uncertain, position) select id, 'XIIIe siècle', 'L''Empire du Mali', 'Une partie de la Haute-Guinée appartient au Manding, cœur de l''Empire du Mali fondé selon la tradition par Soundiata Keïta.', false, 0 from public.countries where code = 'GN';
insert into public.historical_events (country_id, when_label, title, description, is_uncertain, position) select id, 'XVe siècle', 'Les navigateurs européens', 'Des navigateurs portugais longent la côte. Le commerce atlantique commence, y compris, plus tard, la traite des esclaves.', false, 1 from public.countries where code = 'GN';
insert into public.historical_events (country_id, when_label, title, description, is_uncertain, position) select id, 'XVIIIe siècle', 'L''Imamat du Fouta-Djalon', 'Un État musulman se forme dans le Fouta-Djalon, avec Timbo pour capitale. Sa date de fondation, souvent placée vers 1725, est discutée.', true, 2 from public.countries where code = 'GN';
insert into public.historical_events (country_id, when_label, title, description, is_uncertain, position) select id, 'XIXe siècle', 'Samory Touré', 'L''almamy Samory Touré bâtit un vaste État et résiste longtemps à la conquête française. Il est capturé en 1898.', false, 3 from public.countries where code = 'GN';
insert into public.historical_events (country_id, when_label, title, description, is_uncertain, position) select id, 'Fin XIXe siècle', 'La Guinée française', 'Le territoire devient une colonie française, intégrée à l''Afrique-Occidentale française (AOF).', false, 4 from public.countries where code = 'GN';
insert into public.historical_events (country_id, when_label, title, description, is_uncertain, position) select id, '28 septembre 1958', 'Le « non » au référendum', 'Les Guinéens votent massivement « non » à la Communauté proposée par la France. Les femmes jouent un grand rôle dans la mobilisation.', false, 5 from public.countries where code = 'GN';
insert into public.historical_events (country_id, when_label, title, description, is_uncertain, position) select id, '2 octobre 1958', 'L''indépendance', 'La Guinée devient indépendante. Ahmed Sékou Touré est le premier président, jusqu''à sa mort en 1984 ; son régime fut aussi marqué par une dure répression.', false, 6 from public.countries where code = 'GN';
insert into public.historical_events (country_id, when_label, title, description, is_uncertain, position) select id, '1984-2008', 'Lansana Conté', 'Après la mort de Sékou Touré, l''armée prend le pouvoir ; Lansana Conté dirige le pays jusqu''en 2008.', false, 7 from public.countries where code = 'GN';
insert into public.historical_events (country_id, when_label, title, description, is_uncertain, position) select id, '2010', 'Une élection pluraliste', 'Alpha Condé est élu lors d''une élection présidentielle où plusieurs candidats s''affrontent.', false, 8 from public.countries where code = 'GN';
insert into public.historical_events (country_id, when_label, title, description, is_uncertain, position) select id, 'Depuis 2021', 'Une période de transition', 'En septembre 2021, un coup d''État militaire ouvre une période de transition. Pour les événements les plus récents, consulte des sources d''actualité fiables avec un adulte.', false, 9 from public.countries where code = 'GN';
insert into public.natural_sites (country_id, name, description, unesco) select id, 'Le Fouta-Djalon', 'Le « château d''eau de l''Afrique de l''Ouest », où naissent la Gambie et le Bafing (fleuve Sénégal).', false from public.countries where code = 'GN';
insert into public.natural_sites (country_id, name, description, unesco) select id, 'Le mont Nimba', 'Point culminant (environ 1 752 m), réserve inscrite au patrimoine mondial de l''UNESCO, partagée avec la Côte d''Ivoire et le Liberia.', true from public.countries where code = 'GN';
insert into public.natural_sites (country_id, name, description, unesco) select id, 'Les îles de Loos', 'Archipel au large de Conakry : Kassa, Tamara (Fotoba) et Room, avec plages et forêts.', false from public.countries where code = 'GN';
insert into public.natural_sites (country_id, name, description, unesco) select id, 'Les fleuves', 'Le Niger, le Bafing, la Gambie, le Konkouré… La Guinée est un pays d''eau, ce qui permet de produire de l''électricité avec des barrages.', false from public.countries where code = 'GN';
insert into public.natural_sites (country_id, name, description, unesco) select id, 'Les forêts', 'Le massif du Ziama, en Guinée forestière, est une réserve de biosphère reconnue par l''UNESCO, refuge d''éléphants de forêt et de nombreuses espèces.', true from public.countries where code = 'GN';
insert into public.natural_sites (country_id, name, description, unesco) select id, 'Les parcs nationaux', 'Le parc national du Haut-Niger protège des forêts sèches et des chimpanzés ; le parc du Badiar prolonge le Niokolo-Koba du Sénégal.', false from public.countries where code = 'GN';
