insert into public.articles (slug, title, category_id, country_id, scope, difficulty, age_min, age_max, reading_minutes, content_type, scene, intro, glossary, tags, status, editorial_status, validation_note) select 'independance-guinee-1958', '1958 : le « non » qui fit naître la Guinée indépendante', (select id from public.categories where slug = 'histoire'), (select id from public.countries where code = 'GN'), 'GN', 'facile', 8, 12, 4, 'documentaire', 'ville', 'Le 2 octobre 1958, la Guinée devient un pays indépendant. Elle est la première colonie française d''Afrique subsaharienne à faire ce choix. Comment est-ce arrivé ?', '[{"word":"Colonie","definition":"Territoire dirigé par un pays étranger qui l''a conquis."},{"word":"Référendum","definition":"Vote où les citoyens répondent par « oui » ou par « non » à une question."},{"word":"Indépendance","definition":"Situation d''un pays qui se gouverne lui-même."}]'::jsonb, array['indépendance', '1958', 'Sékou Touré', 'référendum']::text[], 'publie', 'verifie', 'Faits principaux largement documentés. La partie sur la période 1958-1984 doit être relue par des historiens guinéens pour le ton et la formulation destinée aux enfants.' on conflict (slug) do nothing;
insert into public.article_sections (article_id, position, heading, paragraphs, did_you_know, uncertainty) select id, 0, 'Une colonie de l''Afrique-Occidentale française', array['À la fin du XIXe siècle, la France conquiert le territoire de l''actuelle Guinée, malgré la résistance de plusieurs chefs, dont Samory Touré. Le pays devient la colonie de la « Guinée française ».', 'Elle fait partie d''un grand ensemble appelé l''Afrique-Occidentale française (AOF), qui regroupe plusieurs colonies gouvernées depuis Dakar.']::text[], null, null from public.articles where slug = 'independance-guinee-1958' on conflict do nothing;
insert into public.article_sections (article_id, position, heading, paragraphs, did_you_know, uncertainty) select id, 1, 'Le référendum du 28 septembre 1958', array['En 1958, le gouvernement français propose aux colonies un référendum : voter « oui » signifie rester dans une « Communauté » avec la France, voter « non » signifie devenir indépendant tout de suite.', 'Les Guinéens votent massivement « non ». Le leader politique Ahmed Sékou Touré avait déclaré : « Nous préférons la pauvreté dans la liberté à la richesse dans l''esclavage. »']::text[], 'La Guinée est le seul territoire de l''AOF à avoir voté « non » à ce référendum.', null from public.articles where slug = 'independance-guinee-1958' on conflict do nothing;
insert into public.article_sections (article_id, position, heading, paragraphs, did_you_know, uncertainty) select id, 2, 'Le 2 octobre 1958, naissance d''un pays', array['Quatre jours après le vote, l''indépendance est proclamée. Ahmed Sékou Touré devient le premier président de la République de Guinée.', 'Le départ de l''administration française est très brutal : de nombreux équipements et documents sont emportés. Le jeune pays doit tout organiser rapidement.', 'En 1960, beaucoup d''autres pays africains deviennent indépendants à leur tour. Le choix de la Guinée a montré que c''était possible.']::text[], null, null from public.articles where slug = 'independance-guinee-1958' on conflict do nothing;
insert into public.article_sections (article_id, position, heading, paragraphs, did_you_know, uncertainty) select id, 3, 'Une histoire à regarder en entier', array['L''histoire d''un pays a des pages joyeuses et des pages difficiles. Après l''indépendance, le régime de Sékou Touré a aussi été marqué par la répression de ses opposants, par exemple au camp Boiro. Les historiens continuent d''étudier cette période.']::text[], null, 'Certains détails (chiffres du vote, circonstances du départ français) varient selon les sources : demande à ton enseignant de les comparer avec toi.' from public.articles where slug = 'independance-guinee-1958' on conflict do nothing;
insert into public.article_sources (article_id, source_id) select a.id, s.id from public.articles a, public.sources s where a.slug = 'independance-guinee-1958' and s.title = 'Histoire de la Guinée contemporaine' and s.publisher is not distinct from 'Manuels scolaires guinéens d''histoire (à compléter par le comité pédagogique)' on conflict do nothing;
insert into public.article_sources (article_id, source_id) select a.id, s.id from public.articles a, public.sources s where a.slug = 'independance-guinee-1958' and s.title = 'Guinée : histoire' and s.publisher is not distinct from 'Encyclopædia Universalis' on conflict do nothing;
insert into public.articles (slug, title, category_id, country_id, scope, difficulty, age_min, age_max, reading_minutes, content_type, scene, intro, glossary, tags, status, editorial_status, validation_note) select 'pourquoi-nom-guinee', 'Pourquoi la Guinée s''appelle-t-elle Guinée ?', (select id from public.categories where slug = 'histoire'), (select id from public.countries where code = 'GN'), 'GN', 'facile', 7, 12, 3, 'explication', 'mer', 'Il existe plusieurs pays qui portent le nom « Guinée » : la Guinée, la Guinée-Bissau, la Guinée équatoriale… et même la Papouasie-Nouvelle-Guinée, en Océanie ! D''où vient ce mot ?', '[{"word":"Hypothèse","definition":"Explication possible qu''on n''a pas encore prouvée."},{"word":"Golfe","definition":"Grande partie de mer qui entre dans les terres."}]'::jsonb, array['nom', 'étymologie', 'golfe de Guinée']::text[], 'publie', 'verifie', null on conflict (slug) do nothing;
insert into public.article_sections (article_id, position, heading, paragraphs, did_you_know, uncertainty) select id, 0, 'Un nom donné à une grande côte', array['À partir du XVe siècle, les navigateurs européens, d''abord portugais, appellent « Guinée » une grande partie de la côte de l''Afrique de l''Ouest. Le grand golfe au sud de l''Afrique de l''Ouest s''appelle d''ailleurs toujours le « golfe de Guinée ».', 'Plus tard, plusieurs colonies reçoivent ce nom : la Guinée française, la Guinée portugaise (aujourd''hui Guinée-Bissau) et la Guinée espagnole (aujourd''hui Guinée équatoriale).']::text[], null, null from public.articles where slug = 'pourquoi-nom-guinee' on conflict do nothing;
insert into public.article_sections (article_id, position, heading, paragraphs, did_you_know, uncertainty) select id, 1, 'Une origine encore discutée', array['Personne ne sait avec certitude d''où vient le mot « Guinée ». Les chercheurs proposent plusieurs explications.', 'Une hypothèse souvent citée le rattache à une expression berbère désignant « le pays des Noirs ». Une autre le rapproche du nom de la ville de Djenné, au Mali. Aucune n''est prouvée.']::text[], null, 'Ici, les spécialistes ne sont pas d''accord : c''est une question ouverte. Un bon lecteur sait reconnaître quand on ne sait pas encore.' from public.articles where slug = 'pourquoi-nom-guinee' on conflict do nothing;
insert into public.article_sections (article_id, position, heading, paragraphs, did_you_know, uncertainty) select id, 2, 'Et la Papouasie-Nouvelle-Guinée ?', array['Au XVIe siècle, un navigateur espagnol a trouvé que les habitants de cette grande île d''Océanie ressemblaient à ceux de la côte de Guinée qu''il connaissait. Il l''a appelée « Nouvelle-Guinée ».']::text[], null, null from public.articles where slug = 'pourquoi-nom-guinee' on conflict do nothing;
insert into public.article_sources (article_id, source_id) select a.id, s.id from public.articles a, public.sources s where a.slug = 'pourquoi-nom-guinee' and s.title = 'Dictionnaire historique de la langue française' and s.publisher is not distinct from 'Le Robert' on conflict do nothing;
insert into public.articles (slug, title, category_id, country_id, scope, difficulty, age_min, age_max, reading_minutes, content_type, scene, intro, glossary, tags, status, editorial_status, validation_note) select 'quatre-regions-naturelles', 'Les quatre régions naturelles de la Guinée', (select id from public.categories where slug = 'geographie'), (select id from public.countries where code = 'GN'), 'GN', 'facile', 7, 12, 4, 'fiche', 'fouta', 'De l''océan aux forêts, en passant par les plateaux et les savanes, la Guinée change de paysage d''une région à l''autre. Les géographes la divisent en quatre régions naturelles.', '[{"word":"Mangrove","definition":"Forêt de palétuviers qui pousse au bord de la mer, dans l''eau salée."},{"word":"Plateau","definition":"Grande étendue de terrain plat située en hauteur."},{"word":"Savane","definition":"Paysage d''herbes hautes avec quelques arbres."}]'::jsonb, array['régions', 'géographie', 'Conakry', 'Labé', 'Kankan', 'N''Zérékoré']::text[], 'publie', 'verifie', null on conflict (slug) do nothing;
insert into public.article_sections (article_id, position, heading, paragraphs, did_you_know, uncertainty) select id, 0, 'La Guinée maritime (Basse-Guinée)', array['C''est la région côtière, le long de l''océan Atlantique. Il y fait chaud et humide, et il pleut beaucoup pendant la saison des pluies.', 'On y trouve Conakry, la capitale, ainsi que Boké et Kindia. Les mangroves, ces forêts qui poussent dans l''eau salée, bordent la côte. On y cultive beaucoup de riz.']::text[], null, null from public.articles where slug = 'quatre-regions-naturelles' on conflict do nothing;
insert into public.article_sections (article_id, position, heading, paragraphs, did_you_know, uncertainty) select id, 1, 'La Moyenne-Guinée (le Fouta-Djalon)', array['C''est une région de plateaux et de montagnes, avec des cascades et un climat plus frais. Labé et Mamou en sont des villes importantes.', 'De nombreux fleuves y prennent leur source : on surnomme le Fouta-Djalon le « château d''eau de l''Afrique de l''Ouest ».']::text[], null, null from public.articles where slug = 'quatre-regions-naturelles' on conflict do nothing;
insert into public.article_sections (article_id, position, heading, paragraphs, did_you_know, uncertainty) select id, 2, 'La Haute-Guinée', array['C''est une région de savanes, plus sèche, traversée par le fleuve Niger et ses affluents. Kankan et Faranah s''y trouvent.', 'Elle fait partie de l''ancien pays mandingue, au cœur de l''histoire de l''Empire du Mali.']::text[], null, null from public.articles where slug = 'quatre-regions-naturelles' on conflict do nothing;
insert into public.article_sections (article_id, position, heading, paragraphs, did_you_know, uncertainty) select id, 3, 'La Guinée forestière', array['Au sud-est, c''est le pays des forêts humides et des montagnes, comme le mont Nimba, point culminant du pays. N''Zérékoré en est la plus grande ville.', 'On y cultive notamment le café, le cacao et le palmier à huile.']::text[], 'La Guinée compte aussi huit régions administratives : Boké, Conakry, Faranah, Kankan, Kindia, Labé, Mamou et N''Zérékoré.', null from public.articles where slug = 'quatre-regions-naturelles' on conflict do nothing;
insert into public.article_sources (article_id, source_id) select a.id, s.id from public.articles a, public.sources s where a.slug = 'quatre-regions-naturelles' and s.title = 'Atlas de la Guinée' and s.publisher is not distinct from 'Éditions Jeune Afrique / manuels de géographie guinéens (référence à préciser)' on conflict do nothing;
insert into public.articles (slug, title, category_id, country_id, scope, difficulty, age_min, age_max, reading_minutes, content_type, scene, intro, glossary, tags, status, editorial_status, validation_note) select 'fouta-djalon-chateau-eau', 'Le Fouta-Djalon, château d''eau de l''Afrique de l''Ouest', (select id from public.categories where slug = 'nature'), (select id from public.countries where code = 'GN'), 'GN', 'moyen', 8, 12, 4, 'documentaire', 'fouta', 'Imagine un massif de plateaux verts, de falaises et de cascades d''où partent des fleuves qui traversent plusieurs pays. C''est le Fouta-Djalon, au cœur de la Guinée.', '[{"word":"Source","definition":"Endroit où l''eau sort de terre et où commence un cours d''eau."},{"word":"Érosion","definition":"Usure lente des sols et des roches par l''eau ou le vent."},{"word":"Grès","definition":"Roche formée de grains de sable collés entre eux."}]'::jsonb, array['Fouta-Djalon', 'fleuves', 'eau', 'Niger', 'Gambie', 'Sénégal']::text[], 'publie', 'verifie', null on conflict (slug) do nothing;
insert into public.article_sections (article_id, position, heading, paragraphs, did_you_know, uncertainty) select id, 0, 'Pourquoi « château d''eau » ?', array['Un château d''eau est un réservoir placé en hauteur qui distribue l''eau. Le Fouta-Djalon joue un rôle semblable : il reçoit beaucoup de pluie, et de nombreux cours d''eau y naissent.', 'Le fleuve Gambie et le Bafing, la principale branche du fleuve Sénégal, y prennent leur source. Le grand fleuve Niger, lui, naît un peu plus au sud-est, dans les hauteurs guinéennes proches de la frontière avec la Sierra Leone.']::text[], 'L''eau qui naît en Guinée traverse ensuite le Mali, le Niger, le Sénégal, la Gambie, la Mauritanie… Des millions de personnes en dépendent.', null from public.articles where slug = 'fouta-djalon-chateau-eau' on conflict do nothing;
insert into public.article_sections (article_id, position, heading, paragraphs, did_you_know, uncertainty) select id, 1, 'Un paysage de plateaux et de cascades', array['Le Fouta-Djalon est formé de hauts plateaux de grès, entaillés par des vallées profondes. On y trouve de nombreuses chutes d''eau.', 'Le climat y est plus frais que sur la côte, surtout la nuit. Des villes comme Labé, Mamou, Pita ou Dalaba s''y trouvent.']::text[], null, null from public.articles where slug = 'fouta-djalon-chateau-eau' on conflict do nothing;
insert into public.article_sections (article_id, position, heading, paragraphs, did_you_know, uncertainty) select id, 2, 'Un patrimoine à protéger', array['Les feux de brousse, la coupe des arbres et l''érosion des sols menacent les sources. Quand les arbres disparaissent, l''eau ruisselle au lieu de s''infiltrer dans le sol.', 'Protéger le Fouta-Djalon, c''est protéger l''eau de toute l''Afrique de l''Ouest. Des pays voisins coopèrent pour cela.']::text[], null, null from public.articles where slug = 'fouta-djalon-chateau-eau' on conflict do nothing;
insert into public.article_sources (article_id, source_id) select a.id, s.id from public.articles a, public.sources s where a.slug = 'fouta-djalon-chateau-eau' and s.title = 'Fouta-Djalon' and s.publisher is not distinct from 'Encyclopædia Universalis' on conflict do nothing;
insert into public.article_sources (article_id, source_id) select a.id, s.id from public.articles a, public.sources s where a.slug = 'fouta-djalon-chateau-eau' and s.title = 'Liste du patrimoine mondial' and s.publisher is not distinct from 'UNESCO' on conflict do nothing;
insert into public.articles (slug, title, category_id, country_id, scope, difficulty, age_min, age_max, reading_minutes, content_type, scene, intro, glossary, tags, status, editorial_status, validation_note) select 'mont-nimba', 'Le mont Nimba, une montagne-trésor', (select id from public.categories where slug = 'nature'), (select id from public.countries where code = 'GN'), 'GN', 'moyen', 8, 12, 3, 'documentaire', 'montagne', 'Le mont Nimba est le plus haut sommet de la Guinée. Partagé avec la Côte d''Ivoire et le Liberia, il abrite des animaux et des plantes qu''on ne trouve nulle part ailleurs.', '[{"word":"Espèce","definition":"Groupe d''êtres vivants semblables qui peuvent se reproduire entre eux."},{"word":"Vivipare","definition":"Se dit d''un animal qui met au monde des petits vivants au lieu de pondre des œufs."}]'::jsonb, array['Nimba', 'UNESCO', 'biodiversité', 'Guinée forestière']::text[], 'publie', 'verifie', null on conflict (slug) do nothing;
insert into public.article_sections (article_id, position, heading, paragraphs, did_you_know, uncertainty) select id, 0, 'Le toit de la Guinée', array['Le sommet du mont Nimba atteint environ 1 752 mètres. Il se trouve en Guinée forestière, au sud-est du pays, là où se rejoignent les frontières de la Guinée, de la Côte d''Ivoire et du Liberia.']::text[], null, null from public.articles where slug = 'mont-nimba' on conflict do nothing;
insert into public.article_sections (article_id, position, heading, paragraphs, did_you_know, uncertainty) select id, 1, 'Un patrimoine mondial', array['En 1981, la Réserve naturelle intégrale du mont Nimba a été inscrite sur la Liste du patrimoine mondial de l''UNESCO. La partie ivoirienne a été ajoutée ensuite.', 'On y trouve des forêts, des prairies de montagne et de nombreuses espèces rares, comme le crapaud vivipare du Nimba, un petit amphibien qui met au monde des petits déjà formés au lieu de pondre des œufs.']::text[], 'Le site figure aussi sur la liste du patrimoine mondial en péril, car il est menacé, notamment par les projets miniers.', null from public.articles where slug = 'mont-nimba' on conflict do nothing;
insert into public.article_sections (article_id, position, heading, paragraphs, did_you_know, uncertainty) select id, 2, 'Concilier richesse et protection', array['La montagne contient aussi du minerai de fer. Les pays doivent trouver comment exploiter leurs ressources sans détruire un milieu unique.']::text[], null, null from public.articles where slug = 'mont-nimba' on conflict do nothing;
insert into public.article_sources (article_id, source_id) select a.id, s.id from public.articles a, public.sources s where a.slug = 'mont-nimba' and s.title = 'Réserve naturelle intégrale du mont Nimba' and s.publisher is not distinct from 'UNESCO' on conflict do nothing;
insert into public.articles (slug, title, category_id, country_id, scope, difficulty, age_min, age_max, reading_minutes, content_type, scene, intro, glossary, tags, status, editorial_status, validation_note) select 'sosso-bala', 'Le Sosso-Bala, un balafon de huit siècles', (select id from public.categories where slug = 'musique'), (select id from public.countries where code = 'GN'), 'GN', 'moyen', 8, 12, 4, 'documentaire', 'musique', 'Dans le village de Niagassola, en Haute-Guinée, une famille veille sur un balafon très ancien et sacré : le Sosso-Bala. La tradition raconte qu''il remonte à l''époque de Soundiata Keïta.', '[{"word":"Griot","definition":"Gardien de la mémoire, musicien et conteur qui transmet l''histoire par la parole."},{"word":"Calebasse","definition":"Fruit séché et vidé, utilisé comme récipient ou pour faire résonner un instrument."},{"word":"Patrimoine immatériel","definition":"Savoirs, musiques, fêtes ou récits qu''on transmet, et qu''on ne peut pas toucher."}]'::jsonb, array['balafon', 'UNESCO', 'griots', 'Niagassola']::text[], 'publie', 'verifie', null on conflict (slug) do nothing;
insert into public.article_sections (article_id, position, heading, paragraphs, did_you_know, uncertainty) select id, 0, 'Qu''est-ce qu''un balafon ?', array['Le balafon est un instrument de musique fait de lames de bois posées sur un cadre. Sous chaque lame est accrochée une calebasse qui fait résonner le son. On le joue avec des baguettes.']::text[], null, null from public.articles where slug = 'sosso-bala' on conflict do nothing;
insert into public.article_sections (article_id, position, heading, paragraphs, did_you_know, uncertainty) select id, 1, 'Le balafon de Soumaoro', array['Selon la tradition orale mandingue, le Sosso-Bala appartenait à Soumaoro Kanté, roi du Sosso, avant de revenir aux Mandingues après la bataille de Kirina, au XIIIe siècle.', 'Depuis, la famille des Kouyaté, une famille de griots, en est la gardienne. Le balafon n''est joué qu''en de rares occasions.']::text[], null, 'L''âge exact de l''instrument ne peut pas être prouvé : c''est la tradition orale qui le rattache au XIIIe siècle.' from public.articles where slug = 'sosso-bala' on conflict do nothing;
insert into public.article_sections (article_id, position, heading, paragraphs, did_you_know, uncertainty) select id, 2, 'Un patrimoine reconnu par le monde', array['En 2001, l''UNESCO a proclamé l''Espace culturel du Sosso-Bala chef-d''œuvre du patrimoine oral et immatériel de l''humanité. Il est aujourd''hui inscrit sur la liste représentative du patrimoine culturel immatériel.', 'Ce qui est protégé, ce n''est pas seulement l''objet : c''est aussi tout le savoir des griots, la musique et les récits qui l''accompagnent.']::text[], null, null from public.articles where slug = 'sosso-bala' on conflict do nothing;
insert into public.article_sources (article_id, source_id) select a.id, s.id from public.articles a, public.sources s where a.slug = 'sosso-bala' and s.title = 'L''Espace culturel du Sosso-Bala' and s.publisher is not distinct from 'UNESCO' on conflict do nothing;
insert into public.article_sources (article_id, source_id) select a.id, s.id from public.articles a, public.sources s where a.slug = 'sosso-bala' and s.title = 'Patrimoine culturel immatériel' and s.publisher is not distinct from 'UNESCO' on conflict do nothing;
insert into public.articles (slug, title, category_id, country_id, scope, difficulty, age_min, age_max, reading_minutes, content_type, scene, intro, glossary, tags, status, editorial_status, validation_note) select 'langues-de-guinee', 'Bonjour en plusieurs langues : les langues de Guinée', (select id from public.categories where slug = 'cultures'), (select id from public.countries where code = 'GN'), 'GN', 'facile', 7, 12, 3, 'fiche', 'ville', 'En Guinée, beaucoup d''enfants parlent deux, trois langues ou plus ! À côté du français, langue officielle, de nombreuses langues nationales sont parlées chaque jour.', '[{"word":"Langue officielle","definition":"Langue utilisée par l''État, l''administration et l''école."},{"word":"Langue nationale","definition":"Langue parlée par une partie de la population d''un pays et reconnue par lui."},{"word":"Locuteur","definition":"Personne qui parle une langue."}]'::jsonb, array['langues', 'pular', 'maninka', 'susu', 'N''Ko']::text[], 'publie', 'a-valider', 'Exemples de vocabulaire et orthographes à faire valider par des locuteurs natifs et l''Académie des langues de Guinée.' on conflict (slug) do nothing;
insert into public.article_sections (article_id, position, heading, paragraphs, did_you_know, uncertainty) select id, 0, 'Des langues très diverses', array['Parmi les langues les plus parlées, on trouve le pular (ou peul), le maninka (ou malinké) et le susu (ou soussou). En Guinée forestière, on parle notamment le kissi, le kpelle (aussi appelé guerzé) et le loma (aussi appelé toma).', 'Il existe bien d''autres langues, comme le baga, le nalu, le landuma, le coniagui ou le bassari. Chaque langue porte une manière de voir le monde.']::text[], null, null from public.articles where slug = 'langues-de-guinee' on conflict do nothing;
insert into public.article_sections (article_id, position, heading, paragraphs, did_you_know, uncertainty) select id, 1, 'Des langues qui voyagent', array['Ces langues ne s''arrêtent pas aux frontières : le pular est parlé dans de nombreux pays d''Afrique de l''Ouest et du Centre, et le maninka est proche du bambara du Mali et du dioula de Côte d''Ivoire.']::text[], 'L''écriture N''Ko a été inventée en 1949 par Solomana Kanté, un savant guinéen, pour écrire les langues mandingues.', null from public.articles where slug = 'langues-de-guinee' on conflict do nothing;
insert into public.article_sections (article_id, position, heading, paragraphs, did_you_know, uncertainty) select id, 2, 'Quelques mots pour commencer', array['En pular, on dit « A jaraama » pour remercier. En maninka, « I ni ce » est une salutation qui sert aussi à remercier.', 'Demande à tes parents, à tes grands-parents ou à tes voisins comment on dit « bonjour » et « merci » dans leurs langues !']::text[], null, 'L''orthographe des langues guinéennes peut varier. Ces exemples doivent être vérifiés par des locuteurs et des linguistes avant publication officielle.' from public.articles where slug = 'langues-de-guinee' on conflict do nothing;
insert into public.article_sources (article_id, source_id) select a.id, s.id from public.articles a, public.sources s where a.slug = 'langues-de-guinee' and s.title = 'Ethnologue — Langues de Guinée' and s.publisher is not distinct from 'SIL International' on conflict do nothing;
insert into public.articles (slug, title, category_id, country_id, scope, difficulty, age_min, age_max, reading_minutes, content_type, scene, intro, glossary, tags, status, editorial_status, validation_note) select 'diversite-culturelle-guinee', 'Une Guinée, mille façons de vivre', (select id from public.categories where slug = 'cultures'), (select id from public.countries where code = 'GN'), 'GN', 'facile', 7, 12, 3, 'explication', 'savane', 'Peuls, Malinkés, Soussous, Kissis, Tomas, Guerzés, Bagas, Nalus et bien d''autres : la Guinée réunit de nombreuses communautés. Leur diversité est une richesse.', '[{"word":"Communauté","definition":"Groupe de personnes qui partagent une langue, une histoire ou des traditions."},{"word":"Parenté à plaisanterie","definition":"Coutume qui permet à certains groupes de se taquiner pour renforcer l''amitié."}]'::jsonb, array['cultures', 'communautés', 'respect']::text[], 'publie', 'a-valider', 'À relire avec des représentants de différentes communautés et régions pour garantir un ton juste et respectueux.' on conflict (slug) do nothing;
insert into public.article_sections (article_id, position, heading, paragraphs, did_you_know, uncertainty) select id, 0, 'Aucune communauté n''est « toute pareille »', array['On parle souvent d''une communauté comme si tout le monde y vivait de la même façon. En réalité, à l''intérieur d''un même groupe, les habitudes changent d''un village à l''autre, d''une ville à l''autre et d''une famille à l''autre.', 'Un enfant de Conakry et un enfant d''un village du Fouta peuvent parler la même langue et avoir pourtant des quotidiens très différents.']::text[], null, null from public.articles where slug = 'diversite-culturelle-guinee' on conflict do nothing;
insert into public.article_sections (article_id, position, heading, paragraphs, did_you_know, uncertainty) select id, 1, 'Des liens qui rapprochent', array['Les communautés de Guinée vivent ensemble depuis très longtemps. Elles se marient entre elles, commercent, partagent des fêtes.', 'Il existe aussi en Afrique de l''Ouest une tradition de « parenté à plaisanterie » : des familles ou des groupes ont le droit de se taquiner gentiment, ce qui aide à éviter les conflits.']::text[], null, null from public.articles where slug = 'diversite-culturelle-guinee' on conflict do nothing;
insert into public.article_sections (article_id, position, heading, paragraphs, did_you_know, uncertainty) select id, 2, 'Apprendre à respecter', array['Connaître les autres cultures aide à mieux les respecter. Poser des questions avec curiosité et politesse est la meilleure façon d''apprendre.']::text[], null, null from public.articles where slug = 'diversite-culturelle-guinee' on conflict do nothing;
insert into public.article_sources (article_id, source_id) select a.id, s.id from public.articles a, public.sources s where a.slug = 'diversite-culturelle-guinee' and s.title = 'Parenté à plaisanterie (sanankuya)' and s.publisher is not distinct from 'Travaux d''anthropologie ouest-africaine (référence à préciser)' on conflict do nothing;
insert into public.articles (slug, title, category_id, country_id, scope, difficulty, age_min, age_max, reading_minutes, content_type, scene, intro, glossary, tags, status, editorial_status, validation_note) select 'bauxite-guinee', 'La bauxite : du sol guinéen à la canette en aluminium', (select id from public.categories where slug = 'economie'), (select id from public.countries where code = 'GN'), 'GN', 'moyen', 9, 12, 4, 'explication', 'savane', 'As-tu déjà tenu une canette, une casserole ou une fenêtre en aluminium ? Ce métal léger vient souvent d''une roche rouge appelée bauxite. Et la Guinée en possède énormément.', '[{"word":"Minerai","definition":"Roche qui contient un métal qu''on peut extraire."},{"word":"Exporter","definition":"Vendre des produits à un autre pays."},{"word":"Recycler","definition":"Transformer un objet usagé pour en fabriquer un nouveau."}]'::jsonb, array['bauxite', 'aluminium', 'mines', 'Boké']::text[], 'publie', 'verifie', null on conflict (slug) do nothing;
insert into public.article_sections (article_id, position, heading, paragraphs, did_you_know, uncertainty) select id, 0, 'Une roche rouge très précieuse', array['La bauxite est une roche riche en aluminium. La Guinée possède parmi les plus grandes réserves de bauxite du monde, notamment dans la région de Boké.', 'La Guinée est aujourd''hui l''un des tout premiers pays exportateurs de bauxite au monde.']::text[], null, null from public.articles where slug = 'bauxite-guinee' on conflict do nothing;
insert into public.article_sections (article_id, position, heading, paragraphs, did_you_know, uncertainty) select id, 1, 'De la roche au métal', array['D''abord, on extrait la bauxite dans des mines. Ensuite, on la transforme en une poudre blanche, l''alumine. Enfin, grâce à beaucoup d''électricité, on transforme l''alumine en aluminium.', 'Plus ces étapes sont réalisées dans le pays, plus elles créent d''emplois et de richesses sur place.']::text[], null, null from public.articles where slug = 'bauxite-guinee' on conflict do nothing;
insert into public.article_sections (article_id, position, heading, paragraphs, did_you_know, uncertainty) select id, 2, 'Les défis', array['Les mines peuvent abîmer les terres agricoles, la poussière gêne les habitants et l''eau peut être polluée. Il faut donc des règles pour protéger l''environnement et les populations.', 'L''aluminium a un grand avantage : il peut être recyclé presque à l''infini !']::text[], null, null from public.articles where slug = 'bauxite-guinee' on conflict do nothing;
insert into public.article_sources (article_id, source_id) select a.id, s.id from public.articles a, public.sources s where a.slug = 'bauxite-guinee' and s.title = 'Mineral Commodity Summaries — Bauxite and Alumina' and s.publisher is not distinct from 'U.S. Geological Survey' on conflict do nothing;
insert into public.articles (slug, title, category_id, country_id, scope, difficulty, age_min, age_max, reading_minutes, content_type, scene, intro, glossary, tags, status, editorial_status, validation_note) select 'camara-laye-enfant-noir', 'Camara Laye et « L''Enfant noir »', (select id from public.categories where slug = 'litterature'), (select id from public.countries where code = 'GN'), 'GN', 'moyen', 9, 12, 3, 'portrait', 'nuit', 'En 1953, un jeune Guinéen publie un livre qui raconte son enfance à Kouroussa. Ce livre, « L''Enfant noir », est devenu l''un des romans africains les plus lus au monde.', '[{"word":"Orfèvre","definition":"Artisan qui fabrique des objets en or ou en argent."},{"word":"Récit autobiographique","definition":"Histoire où l''auteur raconte sa propre vie."}]'::jsonb, array['littérature', 'roman', 'Kouroussa']::text[], 'publie', 'verifie', null on conflict (slug) do nothing;
insert into public.article_sections (article_id, position, heading, paragraphs, did_you_know, uncertainty) select id, 0, 'Un enfant de Kouroussa', array['Camara Laye est né en 1928 à Kouroussa, en Haute-Guinée. Son père était forgeron et orfèvre, un métier entouré de respect et de savoirs secrets.', 'Il part ensuite étudier à Conakry, puis en France, où il écrit le récit de son enfance.']::text[], null, null from public.articles where slug = 'camara-laye-enfant-noir' on conflict do nothing;
insert into public.article_sections (article_id, position, heading, paragraphs, did_you_know, uncertainty) select id, 1, 'Ce que raconte le livre', array['Dans « L''Enfant noir », il décrit l''atelier de son père, la vie chez ses grands-parents, l''école, les cérémonies et le moment où il doit quitter sa famille pour étudier.', 'Le livre a reçu le prix Charles-Veillon en 1954. Il est étudié dans de nombreuses écoles d''Afrique et d''ailleurs.']::text[], null, null from public.articles where slug = 'camara-laye-enfant-noir' on conflict do nothing;
insert into public.article_sections (article_id, position, heading, paragraphs, did_you_know, uncertainty) select id, 2, 'Un écrivain de la mémoire', array['Plus tard, Camara Laye a aussi recueilli la parole des griots, dans « Le Maître de la parole », consacré à l''épopée de Soundiata. Il est mort en 1980.']::text[], null, null from public.articles where slug = 'camara-laye-enfant-noir' on conflict do nothing;
insert into public.article_sources (article_id, source_id) select a.id, s.id from public.articles a, public.sources s where a.slug = 'camara-laye-enfant-noir' and s.title = 'L''Enfant noir' and s.publisher is not distinct from 'Camara Laye, Plon, 1953' on conflict do nothing;
insert into public.articles (slug, title, category_id, country_id, scope, difficulty, age_min, age_max, reading_minutes, content_type, scene, intro, glossary, tags, status, editorial_status, validation_note) select 'empire-du-mali-soundiata', 'Soundiata Keïta et l''Empire du Mali', (select id from public.categories where slug = 'histoire'), (select id from public.countries where code = 'ML'), 'ML', 'moyen', 8, 12, 5, 'documentaire', 'sahel', 'Au XIIIe siècle, un grand empire naît en Afrique de l''Ouest : l''Empire du Mali. Il s''étendait sur une partie des actuels Mali, Guinée, Sénégal, Gambie et Mauritanie. Son fondateur, selon la tradition, s''appelait Soundiata Keïta.', '[{"word":"Épopée","definition":"Long récit qui raconte les exploits de héros, souvent avec du merveilleux."},{"word":"Exil","definition":"Fait de devoir vivre loin de son pays."},{"word":"Mansa","definition":"Titre du souverain de l''Empire du Mali, qui veut dire « roi des rois »."}]'::jsonb, array['Soundiata', 'Empire du Mali', 'Mansa Moussa', 'Kirina']::text[], 'publie', 'verifie', null on conflict (slug) do nothing;
insert into public.article_sections (article_id, position, heading, paragraphs, did_you_know, uncertainty) select id, 0, 'Ce que raconte la tradition orale', array['L''histoire de Soundiata nous est parvenue surtout grâce aux griots, qui la racontent et la chantent depuis des siècles : c''est l''épopée de Soundiata.', 'D''après elle, Soundiata était un enfant qui ne pouvait pas marcher. Moqué, il finit par se lever, grandit, puis part en exil avant de revenir libérer le Manding du roi du Sosso, Soumaoro Kanté.']::text[], null, 'L''épopée mêle des faits historiques et des éléments merveilleux. Elle est précieuse, mais on ne peut pas tout prendre au pied de la lettre. La bataille de Kirina est traditionnellement datée vers 1235.' from public.articles where slug = 'empire-du-mali-soundiata' on conflict do nothing;
insert into public.article_sections (article_id, position, heading, paragraphs, did_you_know, uncertainty) select id, 1, 'Un empire organisé', array['Après sa victoire, Soundiata réunit les chefs du Manding. La tradition rapporte qu''une assemblée tenue à Kouroukan Fouga fixa des règles de vie commune, transmises sous le nom de Charte du Manden.', 'L''empire était riche grâce à l''or, au commerce à travers le Sahara, au sel et à l''agriculture le long du fleuve Niger.']::text[], 'La Charte du Manden est inscrite au patrimoine culturel immatériel de l''UNESCO depuis 2009.', null from public.articles where slug = 'empire-du-mali-soundiata' on conflict do nothing;
insert into public.article_sections (article_id, position, heading, paragraphs, did_you_know, uncertainty) select id, 2, 'Mansa Moussa, le souverain le plus célèbre', array['Au XIVe siècle, Mansa Moussa, un descendant de la famille de Soundiata, fait un pèlerinage à La Mecque en 1324. Des voyageurs et historiens de l''époque racontent qu''il emporta tellement d''or que le prix de ce métal baissa au Caire.', 'Il fit aussi construire des mosquées, dont celle de Djingareyber à Tombouctou, selon la tradition.']::text[], null, null from public.articles where slug = 'empire-du-mali-soundiata' on conflict do nothing;
insert into public.article_sources (article_id, source_id) select a.id, s.id from public.articles a, public.sources s where a.slug = 'empire-du-mali-soundiata' and s.title = 'Soundjata ou l''épopée mandingue' and s.publisher is not distinct from 'Djibril Tamsir Niane, Présence africaine, 1960' on conflict do nothing;
insert into public.article_sources (article_id, source_id) select a.id, s.id from public.articles a, public.sources s where a.slug = 'empire-du-mali-soundiata' and s.title = 'Histoire générale de l''Afrique, volume IV' and s.publisher is not distinct from 'UNESCO' on conflict do nothing;
insert into public.article_sources (article_id, source_id) select a.id, s.id from public.articles a, public.sources s where a.slug = 'empire-du-mali-soundiata' and s.title = 'La Charte du Manden' and s.publisher is not distinct from 'UNESCO' on conflict do nothing;
insert into public.articles (slug, title, category_id, country_id, scope, difficulty, age_min, age_max, reading_minutes, content_type, scene, intro, glossary, tags, status, editorial_status, validation_note) select 'afrique-54-pays', 'L''Afrique, un continent de 54 pays', (select id from public.categories where slug = 'geographie'), (select id from public.countries where code = 'AF'), 'AF', 'facile', 7, 12, 3, 'fiche', 'savane', 'L''Afrique est le deuxième continent le plus grand du monde après l''Asie, et le deuxième le plus peuplé. On y compte 54 pays membres de l''Organisation des Nations unies.', '[{"word":"Continent","definition":"Très grande étendue de terre, comme l''Afrique, l''Asie ou l''Europe."},{"word":"Superficie","definition":"Taille d''une surface, mesurée par exemple en kilomètres carrés."}]'::jsonb, array['continent', 'pays', 'Union africaine', 'Sahara']::text[], 'publie', 'verifie', null on conflict (slug) do nothing;
insert into public.article_sections (article_id, position, heading, paragraphs, did_you_know, uncertainty) select id, 0, 'Un continent immense', array['L''Afrique couvre environ 30 millions de kilomètres carrés. On pourrait y faire entrer à la fois les États-Unis, la Chine, l''Inde et une bonne partie de l''Europe !', 'Elle est entourée par l''océan Atlantique, l''océan Indien, la mer Méditerranée et la mer Rouge.']::text[], null, null from public.articles where slug = 'afrique-54-pays' on conflict do nothing;
insert into public.article_sections (article_id, position, heading, paragraphs, did_you_know, uncertainty) select id, 1, 'Des paysages records', array['Le Sahara est le plus grand désert chaud du monde. Le Nil est l''un des plus longs fleuves de la planète. Le Kilimandjaro, en Tanzanie, est la plus haute montagne d''Afrique (environ 5 895 m).', 'On y trouve aussi de grandes forêts tropicales, comme celle du bassin du Congo, et d''immenses savanes.']::text[], null, null from public.articles where slug = 'afrique-54-pays' on conflict do nothing;
insert into public.article_sections (article_id, position, heading, paragraphs, did_you_know, uncertainty) select id, 2, '54 pays, et une Union', array['Le plus grand pays d''Afrique par la superficie est l''Algérie. Le plus peuplé est le Nigeria.', 'Les pays africains sont réunis dans l''Union africaine, créée en 2002 pour succéder à l''Organisation de l''unité africaine (OUA), fondée en 1963 à Addis-Abeba.']::text[], 'Sur la carte, tu verras aussi le Sahara occidental : son statut n''est pas réglé, il n''est pas compté parmi les 54 pays membres de l''ONU.', null from public.articles where slug = 'afrique-54-pays' on conflict do nothing;
insert into public.article_sources (article_id, source_id) select a.id, s.id from public.articles a, public.sources s where a.slug = 'afrique-54-pays' and s.title = 'États membres' and s.publisher is not distinct from 'Organisation des Nations unies' on conflict do nothing;
insert into public.article_sources (article_id, source_id) select a.id, s.id from public.articles a, public.sources s where a.slug = 'afrique-54-pays' and s.title = 'Union africaine' and s.publisher is not distinct from null on conflict do nothing;
insert into public.articles (slug, title, category_id, country_id, scope, difficulty, age_min, age_max, reading_minutes, content_type, scene, intro, glossary, tags, status, editorial_status, validation_note) select 'comment-fonctionne-un-ordinateur', 'Comment fonctionne un ordinateur ?', (select id from public.categories where slug = 'sciences'), null, 'MONDE', 'facile', 7, 12, 4, 'explication', 'techno', 'Un ordinateur peut afficher des images, jouer de la musique ou t''aider à lire. Pourtant, au fond, il ne comprend qu''une seule chose : des 0 et des 1 !', '[{"word":"Processeur","definition":"Composant qui fait les calculs dans un ordinateur."},{"word":"Binaire","definition":"Système qui n''utilise que deux chiffres : 0 et 1."},{"word":"Programme","definition":"Suite d''instructions qui dit à l''ordinateur quoi faire."}]'::jsonb, array['ordinateur', 'informatique', 'binaire']::text[], 'publie', 'verifie', null on conflict (slug) do nothing;
insert into public.article_sections (article_id, position, heading, paragraphs, did_you_know, uncertainty) select id, 0, 'Entrer, calculer, sortir', array['Un ordinateur fonctionne en trois temps. D''abord, il reçoit des informations : c''est l''entrée (clavier, souris, écran tactile, micro).', 'Ensuite, il les traite grâce à son processeur, le « cerveau » de la machine, qui fait des milliards de petits calculs chaque seconde.', 'Enfin, il donne un résultat : c''est la sortie (écran, haut-parleur, imprimante).']::text[], null, null from public.articles where slug = 'comment-fonctionne-un-ordinateur' on conflict do nothing;
insert into public.article_sections (article_id, position, heading, paragraphs, did_you_know, uncertainty) select id, 1, 'La mémoire', array['La mémoire vive sert au travail du moment, comme un tableau qu''on efface. Le stockage (disque ou carte mémoire) garde les fichiers même quand l''ordinateur est éteint, comme un cahier.']::text[], null, null from public.articles where slug = 'comment-fonctionne-un-ordinateur' on conflict do nothing;
insert into public.article_sections (article_id, position, heading, paragraphs, did_you_know, uncertainty) select id, 2, 'Le langage binaire', array['À l''intérieur, des milliards de minuscules interrupteurs, appelés transistors, sont soit allumés (1), soit éteints (0). En combinant ces 0 et ces 1, on peut représenter des lettres, des nombres, des couleurs et des sons.', 'Les programmes sont des listes d''instructions écrites par des humains : les programmeurs. Toi aussi, tu peux apprendre à programmer !']::text[], 'Ton téléphone est aussi un ordinateur : il a un processeur, une mémoire et un stockage.', null from public.articles where slug = 'comment-fonctionne-un-ordinateur' on conflict do nothing;
insert into public.article_sources (article_id, source_id) select a.id, s.id from public.articles a, public.sources s where a.slug = 'comment-fonctionne-un-ordinateur' and s.title = 'Comment fonctionne un ordinateur' and s.publisher is not distinct from 'Ressources pédagogiques numériques (programme d''informatique du primaire)' on conflict do nothing;
insert into public.articles (slug, title, category_id, country_id, scope, difficulty, age_min, age_max, reading_minutes, content_type, scene, intro, glossary, tags, status, editorial_status, validation_note) select 'os-ishango', 'L''os d''Ishango : compter il y a 20 000 ans', (select id from public.categories where slug = 'sciences'), (select id from public.countries where code = 'AF'), 'AF', 'moyen', 8, 12, 3, 'documentaire', 'fleuve', 'Au bord d''un lac, au cœur de l''Afrique, des chercheurs ont trouvé un petit os couvert d''encoches. Il pourrait être l''un des plus anciens objets mathématiques du monde.', '[{"word":"Encoche","definition":"Petite entaille faite dans un objet."},{"word":"Géologue","definition":"Scientifique qui étudie les roches et la Terre."}]'::jsonb, array['mathématiques', 'préhistoire', 'Ishango']::text[], 'publie', 'verifie', null on conflict (slug) do nothing;
insert into public.article_sections (article_id, position, heading, paragraphs, did_you_know, uncertainty) select id, 0, 'Une découverte au Congo', array['L''os d''Ishango a été découvert en 1950 par le géologue belge Jean de Heinzelin, sur le site d''Ishango, près du lac Édouard, dans l''actuelle République démocratique du Congo.', 'Il est daté d''environ 20 000 ans. Il est aujourd''hui conservé à Bruxelles, en Belgique.']::text[], null, null from public.articles where slug = 'os-ishango' on conflict do nothing;
insert into public.article_sections (article_id, position, heading, paragraphs, did_you_know, uncertainty) select id, 1, 'Des encoches mystérieuses', array['L''os porte des groupes d''encoches gravées en colonnes. Certains chercheurs pensent qu''il servait à compter, d''autres qu''il notait les phases de la Lune.']::text[], null, 'On ne sait pas avec certitude à quoi servait cet objet. Les scientifiques en débattent encore.' from public.articles where slug = 'os-ishango' on conflict do nothing;
insert into public.article_sections (article_id, position, heading, paragraphs, did_you_know, uncertainty) select id, 2, 'Les mathématiques ont une longue histoire africaine', array['Des mathématiques ont été pratiquées très tôt en Afrique : en Égypte ancienne pour mesurer les champs et construire, ou dans les manuscrits de Tombouctou. Les jeux comme l''awalé demandent aussi du calcul et de la stratégie.']::text[], null, null from public.articles where slug = 'os-ishango' on conflict do nothing;
insert into public.article_sources (article_id, source_id) select a.id, s.id from public.articles a, public.sources s where a.slug = 'os-ishango' and s.title = 'L''os d''Ishango' and s.publisher is not distinct from 'Institut royal des sciences naturelles de Belgique' on conflict do nothing;
insert into public.articles (slug, title, category_id, country_id, scope, difficulty, age_min, age_max, reading_minutes, content_type, scene, intro, glossary, tags, status, editorial_status, validation_note) select 'kora-balafon-djembe', 'Kora, balafon, djembé : les instruments mandingues', (select id from public.categories where slug = 'musique'), (select id from public.countries where code = 'AF'), 'AF', 'facile', 7, 12, 3, 'fiche', 'musique', 'Trois instruments sont devenus des ambassadeurs de la musique d''Afrique de l''Ouest dans le monde entier. Apprends à les reconnaître !', '[{"word":"Percussion","definition":"Instrument dont on joue en le frappant."},{"word":"Calice","definition":"Forme de coupe avec un pied."}]'::jsonb, array['kora', 'balafon', 'djembé', 'musique']::text[], 'publie', 'verifie', null on conflict (slug) do nothing;
insert into public.article_sections (article_id, position, heading, paragraphs, did_you_know, uncertainty) select id, 0, 'La kora, la harpe des griots', array['La kora est faite d''une grande calebasse recouverte de peau, d''un long manche et d''environ 21 cordes. On la joue avec les pouces et les index.', 'Elle accompagne les chants des griots. Des musiciens comme Mory Kanté (Guinée) ou Toumani Diabaté (Mali) l''ont fait connaître partout.']::text[], null, null from public.articles where slug = 'kora-balafon-djembe' on conflict do nothing;
insert into public.article_sections (article_id, position, heading, paragraphs, did_you_know, uncertainty) select id, 1, 'Le balafon, l''ancêtre du xylophone', array['Le balafon possède des lames de bois et des calebasses qui résonnent. On joue souvent plusieurs balafons ensemble.']::text[], null, null from public.articles where slug = 'kora-balafon-djembe' on conflict do nothing;
insert into public.article_sections (article_id, position, heading, paragraphs, did_you_know, uncertainty) select id, 2, 'Le djembé, le tambour qui parle', array['Le djembé est un tambour en bois en forme de calice, recouvert d''une peau de chèvre. Selon la façon de frapper, il produit des sons graves ou aigus.', 'Le grand percussionniste guinéen Mamady Keïta a enseigné le djembé dans le monde entier.']::text[], 'Les Ballets africains de Guinée, fondés par Fodéba Keïta, ont fait découvrir ces musiques et ces danses dans de nombreux pays.', null from public.articles where slug = 'kora-balafon-djembe' on conflict do nothing;
insert into public.article_sources (article_id, source_id) select a.id, s.id from public.articles a, public.sources s where a.slug = 'kora-balafon-djembe' and s.title = 'Instruments de musique d''Afrique de l''Ouest' and s.publisher is not distinct from 'Musée du quai Branly – Jacques Chirac (ressources pédagogiques)' on conflict do nothing;
insert into public.articles (slug, title, category_id, country_id, scope, difficulty, age_min, age_max, reading_minutes, content_type, scene, intro, glossary, tags, status, editorial_status, validation_note) select 'griots-oralite', 'Les griots, bibliothèques vivantes', (select id from public.categories where slug = 'litterature'), (select id from public.countries where code = 'AF'), 'AF', 'facile', 7, 12, 3, 'explication', 'nuit', '« En Afrique, un vieillard qui meurt, c''est une bibliothèque qui brûle. » Cette phrase célèbre de l''écrivain malien Amadou Hampâté Bâ rappelle l''importance de la parole.', '[{"word":"Oral","definition":"Qui se transmet par la parole."},{"word":"Généalogie","definition":"Liste des ancêtres d''une famille."},{"word":"Proverbe","definition":"Courte phrase qui exprime une sagesse populaire."}]'::jsonb, array['griots', 'oralité', 'contes', 'proverbes']::text[], 'publie', 'verifie', 'La citation d''Amadou Hampâté Bâ est connue sous plusieurs formulations ; celle-ci est la plus répandue.' on conflict (slug) do nothing;
insert into public.article_sections (article_id, position, heading, paragraphs, did_you_know, uncertainty) select id, 0, 'La parole qui transmet', array['Pendant des siècles, une grande partie de l''histoire de l''Afrique de l''Ouest a été transmise oralement, c''est-à-dire par la parole, de génération en génération.', 'Les griots (on dit aussi « djéli » en langues mandingues) apprennent par cœur les généalogies, les épopées et les chants. Ils conseillent aussi les familles et aident à régler les disputes.']::text[], null, null from public.articles where slug = 'griots-oralite' on conflict do nothing;
insert into public.article_sections (article_id, position, heading, paragraphs, did_you_know, uncertainty) select id, 1, 'Contes, proverbes et devinettes', array['Le soir, on raconte des contes. Ils font rire, peur ou réfléchir, et transmettent souvent une leçon. Les animaux comme le lièvre, l''hyène ou l''araignée y sont souvent les héros.', 'Attention : un conte n''est pas un fait historique. C''est une histoire imaginée pour apprendre et se divertir.']::text[], null, null from public.articles where slug = 'griots-oralite' on conflict do nothing;
insert into public.article_sections (article_id, position, heading, paragraphs, did_you_know, uncertainty) select id, 2, 'Les écrits aussi', array['L''Afrique a aussi une longue tradition d''écriture : hiéroglyphes égyptiens, manuscrits de Tombouctou en arabe et en langues africaines, alphabet N''Ko créé en Guinée…']::text[], null, null from public.articles where slug = 'griots-oralite' on conflict do nothing;
insert into public.article_sources (article_id, source_id) select a.id, s.id from public.articles a, public.sources s where a.slug = 'griots-oralite' and s.title = 'Amkoullel, l''enfant peul' and s.publisher is not distinct from 'Amadou Hampâté Bâ, Actes Sud, 1991' on conflict do nothing;
insert into public.articles (slug, title, category_id, country_id, scope, difficulty, age_min, age_max, reading_minutes, content_type, scene, intro, glossary, tags, status, editorial_status, validation_note) select 'kente-adinkra', 'Kente et adinkra : les tissus qui parlent', (select id from public.categories where slug = 'cultures'), (select id from public.countries where code = 'GH'), 'GH', 'facile', 7, 12, 3, 'documentaire', 'ville', 'Au Ghana, certains tissus racontent des histoires. Leurs couleurs et leurs motifs portent des messages.', '[{"word":"Métier à tisser","definition":"Machine pour fabriquer du tissu en croisant des fils."},{"word":"Symbole","definition":"Dessin ou signe qui représente une idée."}]'::jsonb, array['Ghana', 'tissu', 'kente', 'adinkra', 'Sankofa']::text[], 'publie', 'verifie', null on conflict (slug) do nothing;
insert into public.article_sections (article_id, position, heading, paragraphs, did_you_know, uncertainty) select id, 0, 'Le kente', array['Le kente est tissé en bandes étroites sur des métiers à tisser, puis les bandes sont cousues ensemble. Il est surtout associé aux peuples ashanti et éwé.', 'Chaque couleur a un sens : par exemple, l''or évoque souvent la richesse, le vert la croissance.']::text[], null, 'La signification des couleurs et des motifs peut varier selon les tisserands et les régions.' from public.articles where slug = 'kente-adinkra' on conflict do nothing;
insert into public.article_sections (article_id, position, heading, paragraphs, did_you_know, uncertainty) select id, 1, 'Les symboles adinkra', array['Les adinkra sont des symboles imprimés ou dessinés. Chacun correspond à une idée ou à un proverbe. Le plus connu, « Gye Nyame », exprime la toute-puissance de Dieu. « Sankofa », un oiseau qui regarde en arrière, rappelle qu''il faut connaître son passé pour avancer.']::text[], null, null from public.articles where slug = 'kente-adinkra' on conflict do nothing;
insert into public.article_sources (article_id, source_id) select a.id, s.id from public.articles a, public.sources s where a.slug = 'kente-adinkra' and s.title = 'Adinkra symbols' and s.publisher is not distinct from 'Musées nationaux du Ghana (référence à préciser)' on conflict do nothing;
insert into public.articles (slug, title, category_id, country_id, scope, difficulty, age_min, age_max, reading_minutes, content_type, scene, intro, glossary, tags, status, editorial_status, validation_note) select 'cacao-cote-ivoire-ghana', 'Le voyage d''une fève de cacao', (select id from public.categories where slug = 'economie'), (select id from public.countries where code = 'CI'), 'CI', 'facile', 7, 12, 3, 'explication', 'foret', 'Le chocolat que mangent les enfants du monde entier commence souvent sa vie en Afrique de l''Ouest. La Côte d''Ivoire et le Ghana produisent plus de la moitié du cacao mondial.', '[{"word":"Cabosse","definition":"Fruit du cacaoyer, qui contient les fèves."},{"word":"Fermenter","definition":"Se transformer grâce à de minuscules êtres vivants, comme les levures."},{"word":"Agroforesterie","definition":"Façon de cultiver en gardant ou en plantant des arbres dans les champs."}]'::jsonb, array['cacao', 'agriculture', 'Côte d''Ivoire', 'Ghana']::text[], 'publie', 'verifie', null on conflict (slug) do nothing;
insert into public.article_sections (article_id, position, heading, paragraphs, did_you_know, uncertainty) select id, 0, 'De la cabosse à la fève', array['Le cacaoyer est un arbre des forêts chaudes et humides. Ses fruits, les cabosses, poussent directement sur le tronc.', 'Les agriculteurs ouvrent les cabosses, récupèrent les fèves, les laissent fermenter quelques jours puis les font sécher au soleil.']::text[], null, null from public.articles where slug = 'cacao-cote-ivoire-ghana' on conflict do nothing;
insert into public.article_sections (article_id, position, heading, paragraphs, did_you_know, uncertainty) select id, 1, 'Un produit qui voyage', array['Les fèves séchées sont souvent exportées vers d''autres continents, où elles sont transformées en chocolat. Une part de plus en plus importante est désormais transformée sur place.', 'Transformer le cacao dans le pays permet de créer plus d''emplois et de mieux payer les producteurs.']::text[], 'La Côte d''Ivoire est le premier producteur mondial de cacao ; le Ghana est l''un des tout premiers.', null from public.articles where slug = 'cacao-cote-ivoire-ghana' on conflict do nothing;
insert into public.article_sections (article_id, position, heading, paragraphs, did_you_know, uncertainty) select id, 2, 'Protéger les forêts et les enfants', array['La culture du cacao a fait reculer des forêts. Aujourd''hui, on plante des arbres à côté des cacaoyers (agroforesterie). Les enfants, eux, ont leur place à l''école, pas dans les plantations : des lois les protègent.']::text[], null, null from public.articles where slug = 'cacao-cote-ivoire-ghana' on conflict do nothing;
insert into public.article_sources (article_id, source_id) select a.id, s.id from public.articles a, public.sources s where a.slug = 'cacao-cote-ivoire-ghana' and s.title = 'Statistiques de production' and s.publisher is not distinct from 'Organisation internationale du cacao (ICCO)' on conflict do nothing;
insert into public.articles (slug, title, category_id, country_id, scope, difficulty, age_min, age_max, reading_minutes, content_type, scene, intro, glossary, tags, status, editorial_status, validation_note) select 'fonio-cereale', 'Le fonio, petite graine aux grands pouvoirs', (select id from public.categories where slug = 'economie'), (select id from public.countries where code = 'GN'), 'GN', 'facile', 7, 12, 3, 'documentaire', 'fouta', 'Ses grains sont minuscules, mais le fonio est l''une des plus anciennes céréales cultivées en Afrique de l''Ouest. La Guinée en est le premier producteur mondial.', '[{"word":"Céréale","definition":"Plante dont on mange les grains, comme le riz, le mil ou le maïs."},{"word":"Décorticage","definition":"Fait d''enlever l''enveloppe d''un grain."},{"word":"Gluten","definition":"Protéine présente dans le blé, que certaines personnes ne digèrent pas."}]'::jsonb, array['fonio', 'agriculture', 'alimentation']::text[], 'publie', 'verifie', 'Classement de la Guinée comme premier producteur à confirmer avec les statistiques FAO les plus récentes.' on conflict (slug) do nothing;
insert into public.article_sections (article_id, position, heading, paragraphs, did_you_know, uncertainty) select id, 0, 'Une céréale très ancienne', array['Le fonio est cultivé depuis des milliers d''années en Afrique de l''Ouest. En Guinée, on le cultive beaucoup dans le Fouta-Djalon.', 'Il pousse vite, même sur des sols pauvres et avec peu d''eau : c''est une céréale précieuse face au changement climatique.']::text[], null, null from public.articles where slug = 'fonio-cereale' on conflict do nothing;
insert into public.article_sections (article_id, position, heading, paragraphs, did_you_know, uncertainty) select id, 1, 'Bon pour la santé', array['Le fonio est nourrissant et ne contient pas de gluten. On le prépare en couscous, en bouillie ou avec des sauces.', 'Le travail le plus difficile est le décorticage : enlever l''enveloppe de grains si petits ! Des ingénieurs africains ont inventé des machines pour faciliter ce travail, longtemps fait à la main, surtout par les femmes.']::text[], null, null from public.articles where slug = 'fonio-cereale' on conflict do nothing;
insert into public.article_sources (article_id, source_id) select a.id, s.id from public.articles a, public.sources s where a.slug = 'fonio-cereale' and s.title = 'Le fonio' and s.publisher is not distinct from 'FAO et CIRAD (fiches techniques)' on conflict do nothing;
insert into public.articles (slug, title, category_id, country_id, scope, difficulty, age_min, age_max, reading_minutes, content_type, scene, intro, glossary, tags, status, editorial_status, validation_note) select 'tombouctou-djenne', 'Tombouctou et Djenné, villes de savoir et de terre', (select id from public.categories where slug = 'monuments'), (select id from public.countries where code = 'ML'), 'ML', 'moyen', 8, 12, 4, 'documentaire', 'monument', 'Au Mali, deux villes célèbres racontent la grandeur des empires d''Afrique de l''Ouest : Tombouctou, la ville des manuscrits, et Djenné, la ville de la grande mosquée de terre.', '[{"word":"Manuscrit","definition":"Texte écrit à la main."},{"word":"Banco","definition":"Mélange de terre, d''eau et de paille utilisé pour construire."}]'::jsonb, array['Mali', 'UNESCO', 'manuscrits', 'architecture']::text[], 'publie', 'verifie', null on conflict (slug) do nothing;
insert into public.article_sections (article_id, position, heading, paragraphs, did_you_know, uncertainty) select id, 0, 'Tombouctou, la cité des livres', array['Aux XVe et XVIe siècles, Tombouctou est un grand centre de commerce et d''études. Des savants y enseignent le droit, l''astronomie, les mathématiques et la médecine.', 'Des familles y conservent des milliers de manuscrits anciens. Pendant les violences de 2012, des habitants ont caché et sauvé une grande partie de ces trésors.']::text[], null, null from public.articles where slug = 'tombouctou-djenne' on conflict do nothing;
insert into public.article_sections (article_id, position, heading, paragraphs, did_you_know, uncertainty) select id, 1, 'Djenné et sa grande mosquée', array['La grande mosquée de Djenné est l''un des plus grands bâtiments en terre crue du monde. Le bâtiment actuel a été reconstruit en 1907.', 'Chaque année, les habitants se réunissent pour recouvrir ses murs d''une nouvelle couche de banco (terre mélangée à de l''eau et de la paille) : c''est une grande fête collective.']::text[], null, null from public.articles where slug = 'tombouctou-djenne' on conflict do nothing;
insert into public.article_sections (article_id, position, heading, paragraphs, did_you_know, uncertainty) select id, 2, 'Un patrimoine mondial', array['Tombouctou et les villes anciennes de Djenné sont inscrites au patrimoine mondial de l''UNESCO depuis 1988. Les protéger, c''est protéger une partie de la mémoire de l''humanité.']::text[], null, null from public.articles where slug = 'tombouctou-djenne' on conflict do nothing;
insert into public.article_sources (article_id, source_id) select a.id, s.id from public.articles a, public.sources s where a.slug = 'tombouctou-djenne' and s.title = 'Tombouctou' and s.publisher is not distinct from 'UNESCO' on conflict do nothing;
insert into public.article_sources (article_id, source_id) select a.id, s.id from public.articles a, public.sources s where a.slug = 'tombouctou-djenne' and s.title = 'Villes anciennes de Djenné' and s.publisher is not distinct from 'UNESCO' on conflict do nothing;
insert into public.articles (slug, title, category_id, country_id, scope, difficulty, age_min, age_max, reading_minutes, content_type, scene, intro, glossary, tags, status, editorial_status, validation_note) select 'ile-de-goree', 'L''île de Gorée, un lieu pour se souvenir', (select id from public.categories where slug = 'monuments'), (select id from public.countries where code = 'SN'), 'SN', 'avance', 10, 12, 3, 'documentaire', 'mer', 'Face à Dakar, une petite île aux maisons colorées est devenue un lieu de mémoire pour le monde entier. Elle rappelle une page douloureuse de l''histoire : la traite des esclaves.', '[{"word":"Traite","definition":"Commerce d''êtres humains réduits en esclavage."},{"word":"Déporter","definition":"Emmener quelqu''un de force loin de chez lui."},{"word":"Mémoire","definition":"Souvenir collectif d''un événement passé."}]'::jsonb, array['Sénégal', 'mémoire', 'UNESCO', 'traite']::text[], 'publie', 'verifie', 'Sujet sensible : prévoir une lecture accompagnée par un adulte pour les plus jeunes.' on conflict (slug) do nothing;
insert into public.article_sections (article_id, position, heading, paragraphs, did_you_know, uncertainty) select id, 0, 'Une page difficile de l''histoire', array['Entre le XVe et le XIXe siècle, des millions d''Africains ont été capturés, vendus et déportés de force vers les Amériques à travers l''océan Atlantique. C''est ce qu''on appelle la traite transatlantique.', 'Cette histoire est triste, mais il est important de la connaître pour honorer les victimes et défendre la dignité de chaque être humain.']::text[], null, null from public.articles where slug = 'ile-de-goree' on conflict do nothing;
insert into public.article_sections (article_id, position, heading, paragraphs, did_you_know, uncertainty) select id, 1, 'Gorée, symbole de mémoire', array['L''île de Gorée a été inscrite au patrimoine mondial de l''UNESCO en 1978. On y visite notamment la Maison des Esclaves, devenue un musée et un lieu de recueillement.']::text[], null, 'Les historiens discutent du nombre de captifs réellement passés par Gorée : l''île est avant tout un symbole de toute la traite.' from public.articles where slug = 'ile-de-goree' on conflict do nothing;
insert into public.article_sections (article_id, position, heading, paragraphs, did_you_know, uncertainty) select id, 2, 'Se souvenir pour construire', array['Des chefs d''État, des artistes et des millions de visiteurs viennent à Gorée. Le souvenir aide à construire un monde plus juste.']::text[], null, null from public.articles where slug = 'ile-de-goree' on conflict do nothing;
insert into public.article_sources (article_id, source_id) select a.id, s.id from public.articles a, public.sources s where a.slug = 'ile-de-goree' and s.title = 'Île de Gorée' and s.publisher is not distinct from 'UNESCO' on conflict do nothing;
insert into public.articles (slug, title, category_id, country_id, scope, difficulty, age_min, age_max, reading_minutes, content_type, scene, intro, glossary, tags, status, editorial_status, validation_note) select 'wangari-maathai', 'Wangari Maathai, la femme qui plantait des arbres', (select id from public.categories where slug = 'personnalites'), (select id from public.countries where code = 'AF'), 'AF', 'facile', 7, 12, 3, 'portrait', 'foret', 'Au Kenya, une femme a aidé à planter des dizaines de millions d''arbres. En 2004, elle est devenue la première femme africaine à recevoir le prix Nobel de la paix.', '[{"word":"Doctorat","definition":"Le plus haut diplôme universitaire."},{"word":"Développement durable","definition":"Façon de répondre à nos besoins sans abîmer la planète pour les générations futures."}]'::jsonb, array['Kenya', 'Nobel', 'environnement', 'femmes']::text[], 'publie', 'verifie', null on conflict (slug) do nothing;
insert into public.article_sections (article_id, position, heading, paragraphs, did_you_know, uncertainty) select id, 0, 'Une scientifique', array['Wangari Maathai est née en 1940 au Kenya. Elle a étudié la biologie et est devenue la première femme d''Afrique de l''Est et centrale à obtenir un doctorat.']::text[], null, null from public.articles where slug = 'wangari-maathai' on conflict do nothing;
insert into public.article_sections (article_id, position, heading, paragraphs, did_you_know, uncertainty) select id, 1, 'Le mouvement de la ceinture verte', array['En 1977, elle fonde le Green Belt Movement (mouvement de la ceinture verte). Des femmes plantent des arbres pour lutter contre l''érosion, avoir du bois et de l''eau, et gagner un revenu.', 'Elle s''est aussi battue pour la démocratie et les droits des femmes, ce qui lui a valu d''être arrêtée plusieurs fois.']::text[], 'Elle aimait raconter l''histoire du colibri qui, face à un incendie, transporte l''eau goutte par goutte : « Je fais ce que je peux. »', null from public.articles where slug = 'wangari-maathai' on conflict do nothing;
insert into public.article_sections (article_id, position, heading, paragraphs, did_you_know, uncertainty) select id, 2, 'Le prix Nobel de la paix', array['En 2004, elle reçoit le prix Nobel de la paix « pour sa contribution au développement durable, à la démocratie et à la paix ». Elle est morte en 2011.']::text[], null, null from public.articles where slug = 'wangari-maathai' on conflict do nothing;
insert into public.article_sources (article_id, source_id) select a.id, s.id from public.articles a, public.sources s where a.slug = 'wangari-maathai' and s.title = 'Wangari Maathai — Facts' and s.publisher is not distinct from 'The Nobel Prize' on conflict do nothing;
insert into public.articles (slug, title, category_id, country_id, scope, difficulty, age_min, age_max, reading_minutes, content_type, scene, intro, glossary, tags, status, editorial_status, validation_note) select 'kwame-nkrumah', 'Kwame Nkrumah et le rêve d''une Afrique unie', (select id from public.categories where slug = 'personnalites'), (select id from public.countries where code = 'GH'), 'GH', 'moyen', 9, 12, 3, 'portrait', 'ville', 'En 1957, la Côte-de-l''Or devient le Ghana indépendant. À sa tête, Kwame Nkrumah, un homme qui rêvait d''une Afrique unie.', '[{"word":"Panafricanisme","definition":"Idée selon laquelle les peuples africains doivent s''unir."},{"word":"Autoritaire","definition":"Qui impose ses décisions sans laisser de place aux opposants."}]'::jsonb, array['Ghana', 'indépendance', 'panafricanisme']::text[], 'publie', 'verifie', null on conflict (slug) do nothing;
insert into public.article_sections (article_id, position, heading, paragraphs, did_you_know, uncertainty) select id, 0, 'Le chemin vers l''indépendance', array['Kwame Nkrumah est né en 1909. Après des études aux États-Unis et en Angleterre, il revient en Gold Coast et mène la lutte pour l''indépendance.', 'Le 6 mars 1957, il proclame l''indépendance du Ghana : « Le Ghana, notre pays bien-aimé, est libre pour toujours ! »']::text[], null, null from public.articles where slug = 'kwame-nkrumah' on conflict do nothing;
insert into public.article_sections (article_id, position, heading, paragraphs, did_you_know, uncertainty) select id, 1, 'Le panafricanisme', array['Nkrumah pensait que l''Afrique serait plus forte unie. Il a participé à la création de l''Organisation de l''unité africaine en 1963.', 'Il était très proche de la Guinée : après son renversement en 1966, il a vécu en exil à Conakry, où Sékou Touré l''a nommé co-président de la Guinée à titre honorifique.']::text[], null, null from public.articles where slug = 'kwame-nkrumah' on conflict do nothing;
insert into public.article_sections (article_id, position, heading, paragraphs, did_you_know, uncertainty) select id, 2, 'Un héritage discuté', array['Son pouvoir est aussi devenu autoritaire. Comme pour beaucoup de dirigeants, les historiens étudient à la fois ses réussites et ses erreurs.']::text[], null, null from public.articles where slug = 'kwame-nkrumah' on conflict do nothing;
insert into public.article_sources (article_id, source_id) select a.id, s.id from public.articles a, public.sources s where a.slug = 'kwame-nkrumah' and s.title = 'Histoire générale de l''Afrique, volume VIII' and s.publisher is not distinct from 'UNESCO' on conflict do nothing;
insert into public.articles (slug, title, category_id, country_id, scope, difficulty, age_min, age_max, reading_minutes, content_type, scene, intro, glossary, tags, status, editorial_status, validation_note) select 'sport-en-afrique', 'La Coupe d''Afrique des nations, une grande fête du sport', (select id from public.categories where slug = 'sports'), (select id from public.countries where code = 'AF'), 'AF', 'facile', 7, 12, 3, 'documentaire', 'savane', 'Tous les deux ans environ, les meilleures équipes de football du continent s''affrontent lors de la Coupe d''Afrique des nations (CAN). Des millions de supporters vibrent ensemble !', '[{"word":"Phase finale","definition":"Dernière partie d''une compétition, avec les équipes qualifiées."},{"word":"Persévérance","definition":"Qualité de quelqu''un qui continue malgré les difficultés."}]'::jsonb, array['football', 'CAN', 'sport']::text[], 'publie', 'a-valider', 'Palmarès à revérifier après chaque édition de la CAN ; traduction de « Syli » à confirmer par des locuteurs susu.' on conflict (slug) do nothing;
insert into public.article_sections (article_id, position, heading, paragraphs, did_you_know, uncertainty) select id, 0, 'Une compétition née en 1957', array['La première CAN s''est jouée en 1957 au Soudan, avec seulement trois équipes : l''Égypte, le Soudan et l''Éthiopie. Aujourd''hui, 24 équipes participent à la phase finale.']::text[], null, null from public.articles where slug = 'sport-en-afrique' on conflict do nothing;
insert into public.article_sections (article_id, position, heading, paragraphs, did_you_know, uncertainty) select id, 1, 'Les équipes de nos pays', array['Le Ghana a remporté la CAN quatre fois. La Côte d''Ivoire l''a gagnée trois fois, dont l''édition jouée à domicile début 2024. Le Sénégal l''a remportée pour la première fois en 2022.', 'Le Syli national de Guinée a terminé deuxième en 1976. Le Mali a atteint la finale en 1972.']::text[], '« Syli » veut dire « éléphant » en susu : c''est le surnom de l''équipe de Guinée.', null from public.articles where slug = 'sport-en-afrique' on conflict do nothing;
insert into public.article_sections (article_id, position, heading, paragraphs, did_you_know, uncertainty) select id, 2, 'Plus qu''un jeu', array['Le sport apprend l''esprit d''équipe, le respect des règles et de l''adversaire, et la persévérance. Et il se pratique aussi à l''école, entre amis, filles et garçons !']::text[], null, null from public.articles where slug = 'sport-en-afrique' on conflict do nothing;
insert into public.article_sources (article_id, source_id) select a.id, s.id from public.articles a, public.sources s where a.slug = 'sport-en-afrique' and s.title = 'Palmarès de la Coupe d''Afrique des nations' and s.publisher is not distinct from 'Confédération africaine de football (CAF)' on conflict do nothing;
insert into public.articles (slug, title, category_id, country_id, scope, difficulty, age_min, age_max, reading_minutes, content_type, scene, intro, glossary, tags, status, editorial_status, validation_note) select 'energie-solaire-afrique', 'Le soleil, l''énergie de l''Afrique de demain', (select id from public.categories where slug = 'demain'), (select id from public.countries where code = 'AF'), 'AF', 'facile', 7, 12, 3, 'explication', 'techno', 'L''Afrique reçoit énormément de soleil. Grâce aux panneaux solaires, cette lumière peut devenir de l''électricité pour les écoles, les maisons et les centres de santé.', '[{"word":"Photovoltaïque","definition":"Qui transforme la lumière en électricité."},{"word":"Batterie","definition":"Réserve qui stocke l''électricité pour plus tard."}]'::jsonb, array['énergie', 'solaire', 'climat', 'avenir']::text[], 'publie', 'verifie', null on conflict (slug) do nothing;
insert into public.article_sections (article_id, position, heading, paragraphs, did_you_know, uncertainty) select id, 0, 'Comment marche un panneau solaire ?', array['Un panneau solaire est fait de cellules qui transforment la lumière en électricité : c''est l''effet photovoltaïque. L''électricité peut être utilisée tout de suite ou stockée dans une batterie pour la nuit.']::text[], null, null from public.articles where slug = 'energie-solaire-afrique' on conflict do nothing;
insert into public.article_sections (article_id, position, heading, paragraphs, did_you_know, uncertainty) select id, 1, 'Pourquoi c''est important', array['Des centaines de millions de personnes en Afrique n''ont pas encore accès à l''électricité. Les mini-réseaux et les kits solaires permettent d''éclairer des villages éloignés des grandes lignes électriques.', 'L''énergie solaire ne rejette pas de fumée et aide à lutter contre le changement climatique.']::text[], null, null from public.articles where slug = 'energie-solaire-afrique' on conflict do nothing;
insert into public.article_sections (article_id, position, heading, paragraphs, did_you_know, uncertainty) select id, 2, 'Les métiers de demain', array['Installer, réparer, inventer : l''énergie solaire crée de nouveaux métiers. Peut-être le tien ?']::text[], null, null from public.articles where slug = 'energie-solaire-afrique' on conflict do nothing;
insert into public.article_sources (article_id, source_id) select a.id, s.id from public.articles a, public.sources s where a.slug = 'energie-solaire-afrique' and s.title = 'Africa Energy Outlook' and s.publisher is not distinct from 'Agence internationale de l''énergie' on conflict do nothing;
insert into public.articles (slug, title, category_id, country_id, scope, difficulty, age_min, age_max, reading_minutes, content_type, scene, intro, glossary, tags, status, editorial_status, validation_note) select 'numerique-afrique', 'Le téléphone qui a changé la vie : l''Afrique et le numérique', (select id from public.categories where slug = 'demain'), (select id from public.countries where code = 'AF'), 'AF', 'moyen', 9, 12, 3, 'explication', 'techno', 'En Afrique, beaucoup de gens ont découvert Internet directement sur le téléphone portable. Et des inventions africaines ont changé le quotidien de millions de personnes.', '[{"word":"Application","definition":"Programme installé sur un téléphone ou un ordinateur."},{"word":"Mobile money","definition":"Argent qu''on envoie et reçoit avec son téléphone."}]'::jsonb, array['numérique', 'mobile', 'innovation']::text[], 'publie', 'verifie', null on conflict (slug) do nothing;
insert into public.article_sections (article_id, position, heading, paragraphs, did_you_know, uncertainty) select id, 0, 'L''argent dans le téléphone', array['En 2007, au Kenya, un service appelé M-Pesa permet d''envoyer de l''argent avec un simple SMS. Depuis, le « mobile money » s''est répandu dans de nombreux pays africains, y compris en Guinée.']::text[], null, null from public.articles where slug = 'numerique-afrique' on conflict do nothing;
insert into public.article_sections (article_id, position, heading, paragraphs, did_you_know, uncertainty) select id, 1, 'Apprendre et créer', array['Des jeunes Africains créent des applications pour l''agriculture, la santé ou l''éducation. Des écoles de programmation ouvrent dans de nombreuses villes.', 'Pour réussir dans le numérique, il faut… savoir bien lire ! Comprendre un texte, c''est la première compétence du programmeur.']::text[], null, null from public.articles where slug = 'numerique-afrique' on conflict do nothing;
insert into public.article_sections (article_id, position, heading, paragraphs, did_you_know, uncertainty) select id, 2, 'Utiliser les écrans avec sagesse', array['Le numérique est un outil formidable, mais il faut aussi faire des pauses, jouer dehors et ne jamais partager ses informations personnelles avec des inconnus.']::text[], null, null from public.articles where slug = 'numerique-afrique' on conflict do nothing;
insert into public.article_sources (article_id, source_id) select a.id, s.id from public.articles a, public.sources s where a.slug = 'numerique-afrique' and s.title = 'The Mobile Economy Sub-Saharan Africa' and s.publisher is not distinct from 'GSMA' on conflict do nothing;
insert into public.stories (slug, title, genre, disclaimer, scope, age_min, reading_minutes, scene, summary, interactive, start_node, credits, status) values ('le-secret-de-la-source', 'Le secret de la source', 'fiction', 'Histoire inventée. Les paysages du Fouta-Djalon et le rôle de ses sources, eux, sont bien réels.', 'GN', 7, 6, 'fouta', 'Près de Labé, Aïssatou remarque que le ruisseau du village s''affaiblit. Elle décide de remonter jusqu''à la source. C''est toi qui choisis son chemin !', true, 'debut', 'Texte original CONTEVERSE.', 'publie') on conflict (slug) do nothing;
insert into public.story_nodes (story_id, node_key, paragraphs, scene, ending_title, ending_message) select id, 'debut', array['Chaque matin, Aïssatou, dix ans, va chercher de l''eau au ruisseau qui coule près de son village, non loin de Labé.', 'Mais ce matin, l''eau ne chante plus : elle murmure à peine entre les pierres. « Pourquoi le ruisseau devient-il si petit ? » se demande-t-elle.', 'Sa grand-mère lui répond : « Le ruisseau naît là-haut, sur le plateau. Va voir la source, et tu comprendras. »']::text[], 'fouta', null, null from public.stories where slug = 'le-secret-de-la-source' on conflict do nothing;
insert into public.story_nodes (story_id, node_key, paragraphs, scene, ending_title, ending_message) select id, 'cascades', array['Aïssatou grimpe le long des cascades. L''air devient plus frais, les fougères brillent de rosée.', 'Au détour du chemin, elle découvre une colline toute noire : un feu de brousse a brûlé les arbres. Sans leurs racines, la terre s''est envolée avec la pluie.']::text[], 'fleuve', null, null from public.stories where slug = 'le-secret-de-la-source' on conflict do nothing;
insert into public.story_nodes (story_id, node_key, paragraphs, scene, ending_title, ending_message) select id, 'mamadou', array['Mamadou adore les cartes. Il dessine le chemin sur un cahier : « Si on suit le ruisseau vers l''amont, on arrivera forcément à la source ! »', 'En marchant, ils comptent les arbres. Plus ils montent, moins il y en a. « Regarde, dit Mamadou, ici, le sol est tout sec et craquelé. »']::text[], 'savane', null, null from public.stories where slug = 'le-secret-de-la-source' on conflict do nothing;
insert into public.story_nodes (story_id, node_key, paragraphs, scene, ending_title, ending_message) select id, 'eleveur', array['Un vieil éleveur fait boire ses vaches. Il leur raconte : « Quand j''étais petit, cette colline était une forêt. La forêt gardait la pluie comme une éponge, et la source coulait toute l''année. »', 'Aïssatou comprend : les arbres sont les gardiens de l''eau.']::text[], 'fouta', null, null from public.stories where slug = 'le-secret-de-la-source' on conflict do nothing;
insert into public.story_nodes (story_id, node_key, paragraphs, scene, ending_title, ending_message) select id, 'source', array['Enfin, voici la source : un mince filet d''eau sort de la roche, à l''ombre de quelques arbres survivants.', 'Aïssatou pose la main dans l''eau glacée. Cette petite source nourrit son ruisseau, qui rejoint une rivière, qui rejoint un fleuve qui traverse plusieurs pays. « Tout commence ici », murmure-t-elle.']::text[], 'foret', null, null from public.stories where slug = 'le-secret-de-la-source' on conflict do nothing;
insert into public.story_nodes (story_id, node_key, paragraphs, scene, ending_title, ending_message) select id, 'village', array['Au village, Aïssatou raconte tout. Les enfants de l''école décident de planter des arbres autour de la source avant la saison des pluies, et les adultes s''organisent pour éviter les feux de brousse.']::text[], 'savane', null, null from public.stories where slug = 'le-secret-de-la-source' on conflict do nothing;
insert into public.story_nodes (story_id, node_key, paragraphs, scene, ending_title, ending_message) select id, 'fin-arbres', array['Les années passent. Les jeunes arbres grandissent, et le ruisseau se remet doucement à chanter.']::text[], 'foret', 'Gardienne de la source', 'Tu as compris que les arbres protègent l''eau. Le Fouta-Djalon est le « château d''eau » de l''Afrique de l''Ouest : le protéger aide des millions de personnes.' from public.stories where slug = 'le-secret-de-la-source' on conflict do nothing;
insert into public.story_nodes (story_id, node_key, paragraphs, scene, ending_title, ending_message) select id, 'fin-radio', array['Le poème d''Aïssatou passe à la radio. Dans d''autres villages, des enfants l''entendent et plantent eux aussi des arbres.']::text[], 'ville', 'La voix de l''eau', 'Les mots peuvent changer les choses ! Lire et écrire, c''est aussi agir pour sa communauté.' from public.stories where slug = 'le-secret-de-la-source' on conflict do nothing;
insert into public.story_choices (story_id, from_node, to_node, label, position) select id, 'debut', 'cascades', 'Prendre le sentier des cascades', 0 from public.stories where slug = 'le-secret-de-la-source';
insert into public.story_choices (story_id, from_node, to_node, label, position) select id, 'debut', 'mamadou', 'Demander à son ami Mamadou de l''accompagner', 1 from public.stories where slug = 'le-secret-de-la-source';
insert into public.story_choices (story_id, from_node, to_node, label, position) select id, 'cascades', 'source', 'Continuer jusqu''à la source', 0 from public.stories where slug = 'le-secret-de-la-source';
insert into public.story_choices (story_id, from_node, to_node, label, position) select id, 'cascades', 'village', 'Redescendre prévenir le village', 1 from public.stories where slug = 'le-secret-de-la-source';
insert into public.story_choices (story_id, from_node, to_node, label, position) select id, 'mamadou', 'source', 'Noter tout dans le cahier et continuer', 0 from public.stories where slug = 'le-secret-de-la-source';
insert into public.story_choices (story_id, from_node, to_node, label, position) select id, 'mamadou', 'eleveur', 'Interroger un vieil éleveur sur le chemin', 1 from public.stories where slug = 'le-secret-de-la-source';
insert into public.story_choices (story_id, from_node, to_node, label, position) select id, 'eleveur', 'source', 'Aller jusqu''à la source', 0 from public.stories where slug = 'le-secret-de-la-source';
insert into public.story_choices (story_id, from_node, to_node, label, position) select id, 'source', 'village', 'Rentrer avec une idée', 0 from public.stories where slug = 'le-secret-de-la-source';
insert into public.story_choices (story_id, from_node, to_node, label, position) select id, 'village', 'fin-arbres', 'Planter des arbres avec l''école', 0 from public.stories where slug = 'le-secret-de-la-source';
insert into public.story_choices (story_id, from_node, to_node, label, position) select id, 'village', 'fin-radio', 'Écrire un poème pour la radio locale', 1 from public.stories where slug = 'le-secret-de-la-source';
insert into public.stories (slug, title, genre, disclaimer, scope, age_min, reading_minutes, scene, summary, interactive, start_node, credits, status) values ('le-lievre-et-la-calebasse-de-sagesse', 'Le lièvre et la calebasse de sagesse', 'conte', 'Conte. Ce récit est une création originale CONTEVERSE, inspirée de la grande tradition ouest-africaine des contes du lièvre malin. Ce n''est pas un fait réel.', 'AF', 7, 4, 'savane', 'Le lièvre veut garder toute la sagesse du monde pour lui seul. Mais la sagesse a-t-elle envie d''être enfermée ?', true, 'debut', 'Texte original CONTEVERSE, inspiré des contes traditionnels de lièvre d''Afrique de l''Ouest.', 'publie') on conflict (slug) do nothing;
insert into public.story_nodes (story_id, node_key, paragraphs, scene, ending_title, ending_message) select id, 'debut', array['Il était une fois, dans la savane, un lièvre très malin qui voulait devenir le plus sage de tous les animaux.', 'Un jour, il trouve une calebasse magique. Une voix en sort : « Je contiens toute la sagesse du monde. Que veux-tu faire de moi ? »']::text[], 'savane', null, null from public.stories where slug = 'le-lievre-et-la-calebasse-de-sagesse' on conflict do nothing;
insert into public.story_nodes (story_id, node_key, paragraphs, scene, ending_title, ending_message) select id, 'baobab', array['Le lièvre attache la calebasse devant son ventre et essaie de grimper au baobab. Mais la calebasse le gêne : il glisse, tombe, recommence.', 'Un petit margouillat le regarde et rit : « Lièvre, pourquoi ne la mets-tu pas sur ton dos ? Tu grimperais facilement ! »']::text[], 'savane', null, null from public.stories where slug = 'le-lievre-et-la-calebasse-de-sagesse' on conflict do nothing;
insert into public.story_nodes (story_id, node_key, paragraphs, scene, ending_title, ending_message) select id, 'chute', array['Le lièvre, vexé, refuse le conseil. Il grimpe encore… et la calebasse se brise au pied de l''arbre ! La sagesse s''envole et se pose un peu partout : sur l''oiseau, l''éléphant, la fourmi et le margouillat.']::text[], 'savane', 'La sagesse éparpillée', 'Personne ne possède toute la sagesse : chacun en a un peu. Écouter les autres, même les plus petits, rend plus sage.' from public.stories where slug = 'le-lievre-et-la-calebasse-de-sagesse' on conflict do nothing;
insert into public.story_nodes (story_id, node_key, paragraphs, scene, ending_title, ending_message) select id, 'lecon', array['Le lièvre s''arrête. « Ce petit margouillat vient de me donner un conseil que je n''avais pas trouvé… Alors je ne possède pas toute la sagesse ! »', 'Il redescend et ouvre la calebasse devant tous les animaux.']::text[], 'savane', null, null from public.stories where slug = 'le-lievre-et-la-calebasse-de-sagesse' on conflict do nothing;
insert into public.story_nodes (story_id, node_key, paragraphs, scene, ending_title, ending_message) select id, 'partage', array['Le soir, autour du feu, chaque animal pose une question à la calebasse, et chacun raconte aussi ce qu''il sait : l''oiseau parle du ciel, la tortue du temps qui passe, la fourmi du travail en équipe.', 'La calebasse se met à briller : plus on partage la sagesse, plus elle grandit !']::text[], 'nuit', 'La sagesse partagée', 'Le savoir grandit quand on le partage. C''est pour cela qu''on raconte des contes et qu''on écrit des livres.' from public.stories where slug = 'le-lievre-et-la-calebasse-de-sagesse' on conflict do nothing;
insert into public.story_choices (story_id, from_node, to_node, label, position) select id, 'debut', 'baobab', 'La cacher en haut du grand baobab', 0 from public.stories where slug = 'le-lievre-et-la-calebasse-de-sagesse';
insert into public.story_choices (story_id, from_node, to_node, label, position) select id, 'debut', 'partage', 'La montrer aux autres animaux', 1 from public.stories where slug = 'le-lievre-et-la-calebasse-de-sagesse';
insert into public.story_choices (story_id, from_node, to_node, label, position) select id, 'baobab', 'lecon', 'Écouter le margouillat', 0 from public.stories where slug = 'le-lievre-et-la-calebasse-de-sagesse';
insert into public.story_choices (story_id, from_node, to_node, label, position) select id, 'baobab', 'chute', 'Se vexer et continuer seul', 1 from public.stories where slug = 'le-lievre-et-la-calebasse-de-sagesse';
insert into public.story_choices (story_id, from_node, to_node, label, position) select id, 'lecon', 'partage', 'Voir ce qui se passe', 0 from public.stories where slug = 'le-lievre-et-la-calebasse-de-sagesse';
insert into public.stories (slug, title, genre, disclaimer, scope, age_min, reading_minutes, scene, summary, interactive, start_node, credits, status) values ('soundiata-l-enfant-qui-se-leva', 'Soundiata, l''enfant qui se leva', 'epopee', 'Récit inspiré de l''épopée mandingue, transmise par les griots. L''épopée mêle histoire et merveilleux : Soundiata Keïta a bien existé et fondé l''Empire du Mali au XIIIe siècle, mais certains épisodes relèvent de la légende.', 'ML', 8, 5, 'sahel', 'Moqué parce qu''il ne pouvait pas marcher, le jeune Soundiata va devenir le fondateur d''un empire. Une histoire de courage et de persévérance.', false, '1', 'Réécriture originale CONTEVERSE à partir des grandes lignes de l''épopée mandingue (tradition orale).', 'publie') on conflict (slug) do nothing;
insert into public.story_nodes (story_id, node_key, paragraphs, scene, ending_title, ending_message) select id, '1', array['Il y a très longtemps, au pays du Manding, naquit un enfant nommé Soundiata. Sa mère s''appelait Sogolon. Les griots racontent que l''enfant ne parvenait pas à marcher et qu''il se déplaçait à quatre pattes, même à sept ans.', 'Certains se moquaient de lui et de sa mère. Sogolon pleurait souvent, mais elle ne cessait pas de croire en son fils.']::text[], 'sahel', null, null from public.stories where slug = 'soundiata-l-enfant-qui-se-leva' on conflict do nothing;
insert into public.story_nodes (story_id, node_key, paragraphs, scene, ending_title, ending_message) select id, '2', array['Un jour, après une moquerie de trop, Soundiata déclara : « Aujourd''hui, je vais marcher. » On lui apporta une grande barre de fer forgée par les forgerons.', 'S''appuyant de toutes ses forces, il se redressa. La barre se courba comme un arc… et Soundiata se tint debout ! Les griots chantent encore ce moment.']::text[], 'sahel', null, null from public.stories where slug = 'soundiata-l-enfant-qui-se-leva' on conflict do nothing;
insert into public.story_nodes (story_id, node_key, paragraphs, scene, ending_title, ending_message) select id, '3', array['Plus tard, Soundiata dut partir en exil avec sa mère et ses frères et sœurs. Pendant ces années loin de chez lui, il apprit la chasse, la patience et l''art de diriger.', 'Pendant ce temps, le roi du Sosso, Soumaoro Kanté, avait pris le pouvoir sur le Manding.']::text[], 'savane', null, null from public.stories where slug = 'soundiata-l-enfant-qui-se-leva' on conflict do nothing;
insert into public.story_nodes (story_id, node_key, paragraphs, scene, ending_title, ending_message) select id, '4', array['Les habitants du Manding vinrent chercher Soundiata. Il rassembla une alliance et affronta Soumaoro lors de la bataille de Kirina, que la tradition situe vers 1235.', 'Victorieux, Soundiata réunit les chefs et donna naissance à l''Empire du Mali, qui deviendra l''un des plus grands empires de l''histoire de l''Afrique.']::text[], 'sahel', 'Le courage de se lever', 'Soundiata montre que la persévérance peut tout changer. Pour aller plus loin, lis l''article « Soundiata Keïta et l''Empire du Mali » : tu y découvriras ce que disent les historiens.' from public.stories where slug = 'soundiata-l-enfant-qui-se-leva' on conflict do nothing;
insert into public.story_choices (story_id, from_node, to_node, label, position) select id, '1', '2', 'Continuer', 0 from public.stories where slug = 'soundiata-l-enfant-qui-se-leva';
insert into public.story_choices (story_id, from_node, to_node, label, position) select id, '2', '3', 'Continuer', 0 from public.stories where slug = 'soundiata-l-enfant-qui-se-leva';
insert into public.story_choices (story_id, from_node, to_node, label, position) select id, '3', '4', 'Continuer', 0 from public.stories where slug = 'soundiata-l-enfant-qui-se-leva';
insert into public.stories (slug, title, genre, disclaimer, scope, age_min, reading_minutes, scene, summary, interactive, start_node, credits, status) values ('fatou-et-le-village-lumiere', 'Fatou et le village lumière', 'fiction', 'Histoire inventée qui se passe dans un futur proche. Les technologies décrites (panneaux solaires, batteries) existent déjà.', 'AF', 8, 5, 'techno', 'Dans le village de Fatou, il n''y a pas d''électricité le soir. Avec son club de sciences, elle a une idée lumineuse. À toi de choisir ce qu''elle va construire !', true, 'debut', 'Texte original CONTEVERSE.', 'publie') on conflict (slug) do nothing;
insert into public.story_nodes (story_id, node_key, paragraphs, scene, ending_title, ending_message) select id, 'debut', array['Dans le village de Fatou, quand le soleil se couche, tout devient noir. Les enfants font leurs devoirs à la lampe à pétrole, qui sent mauvais et fait tousser.', 'Au club de sciences, la maîtresse montre un petit panneau solaire : « Le soleil nous donne de la lumière gratuite toute la journée. Comment la garder pour la nuit ? »']::text[], 'nuit', null, null from public.stories where slug = 'fatou-et-le-village-lumiere' on conflict do nothing;
insert into public.story_nodes (story_id, node_key, paragraphs, scene, ending_title, ending_message) select id, 'lampes', array['Fatou et ses amis apprennent à relier un panneau, une petite batterie et une ampoule LED. Il faut lire la notice très attentivement : un fil mal branché, et rien ne s''allume !', 'Le premier soir, dix lampes s''allument. Les enfants peuvent lire leurs livres dehors, sous la véranda.']::text[], 'techno', null, null from public.stories where slug = 'fatou-et-le-village-lumiere' on conflict do nothing;
insert into public.story_nodes (story_id, node_key, paragraphs, scene, ending_title, ending_message) select id, 'sante', array['L''infirmière du village explique qu''elle doit parfois soigner la nuit avec une simple torche. Le club installe des panneaux sur le toit de la case de santé.', 'Désormais, un réfrigérateur solaire garde les vaccins au frais.']::text[], 'techno', null, null from public.stories where slug = 'fatou-et-le-village-lumiere' on conflict do nothing;
insert into public.story_nodes (story_id, node_key, paragraphs, scene, ending_title, ending_message) select id, 'fin-biblio', array['Chaque soir, la bibliothèque du soir accueille les enfants et les parents. On y lit des contes, des livres de sciences, et même des articles de CONTEVERSE !']::text[], 'nuit', 'Le village lumière', 'La lumière aide à apprendre. L''énergie solaire peut éclairer les écoles et les maisons partout en Afrique.' from public.stories where slug = 'fatou-et-le-village-lumiere' on conflict do nothing;
insert into public.story_nodes (story_id, node_key, paragraphs, scene, ending_title, ending_message) select id, 'fin-atelier', array['L''atelier de réparation devient un vrai petit métier pour des jeunes du village. Fatou rêve maintenant de devenir ingénieure en énergie.']::text[], 'techno', 'Ingénieure de demain', 'Les métiers de l''énergie solaire sont des métiers d''avenir. Et tout commence par la curiosité et la lecture !' from public.stories where slug = 'fatou-et-le-village-lumiere' on conflict do nothing;
insert into public.story_choices (story_id, from_node, to_node, label, position) select id, 'debut', 'lampes', 'Fabriquer des lampes solaires pour les élèves', 0 from public.stories where slug = 'fatou-et-le-village-lumiere';
insert into public.story_choices (story_id, from_node, to_node, label, position) select id, 'debut', 'sante', 'Éclairer d''abord la case de santé', 1 from public.stories where slug = 'fatou-et-le-village-lumiere';
insert into public.story_choices (story_id, from_node, to_node, label, position) select id, 'lampes', 'fin-biblio', 'Créer une bibliothèque du soir', 0 from public.stories where slug = 'fatou-et-le-village-lumiere';
insert into public.story_choices (story_id, from_node, to_node, label, position) select id, 'lampes', 'fin-atelier', 'Apprendre aux adultes à réparer les lampes', 1 from public.stories where slug = 'fatou-et-le-village-lumiere';
insert into public.story_choices (story_id, from_node, to_node, label, position) select id, 'sante', 'lampes', 'Continuer avec les lampes pour l''école', 0 from public.stories where slug = 'fatou-et-le-village-lumiere';
